window.__D("text/zohar-chadash/c010",{"p":[[9514015392,"<p>וַיִּבֶן נֹחַ מִזְבֵּחַ. (בראשית ח) מַאי וַיִּבֶן נֹחַ. אֶלָּא נֹחַ אִישׁ צַדִּיק. וַיִּבֶן מִזְבֵּחַ דָּא שְׁכִינְתָּא. בִּנְיָנָא דִּילֵהּ בֵּין דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא. וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְהוֹרָה. מַאי בְּהֵמָה לְעֵלָּא וְעוֹף לְתַתָּא טָהוֹר. אֶלָּא בְּהֵמָה דָּא שׁוֹר עִלָּאָה דְאִקְּרֵי אָדָם עִלָּאָה דִּלְעֵלָּא, דְּאִתְּמַר בֵּהּ מַקְרִין מַפְרִיס. וְאוֹקְמוּהּ מִקֶּרֶן כְּתִיב, קֶרֶן אַחַת הֲוָה לֵהּ בְּמִצְחֵהּ. וְהַאי אִיהוּ קֶרֶן הַיּוֹבֵל דְּמִנֵּהּ קֶרֶן פְּנֵי מֹשֶׁה. שׁוֹר דָּא אִיהוּ פָּר. פָּר אִיהוּ דִּינָא עִם ו' אִתְעֲבִיד פּוּר רַחֲמֵי סְלִיחָה וְעַל שְׁמֵהּ אִקְּרֵי צוֹם כִּפּוּר. מַאי כ' בְּתוֹסֶפֶת פּוּ\"ר. אֶלָּא דָּא כֶּתֶר מַלְכוּת. תָּא חֲזֵי לֵית שְׁכִינְתָּא דְּלָא אִתְעֲבִידַת כִּתְרָא לְהַהִיא דִּלְתַתָּא מִנַּהּ. וּבְגִין דָּא שְׁכִינְתָּא עִלָּאָה אִיהִי כֶּתֶר מַלְכוּת. וּמַלְכוּת אִתְקְרִיאַת צוֹם דִילָהּ אִיהִי מַלְכוּת. וּמַלְכוּת אִתְקְרִיאַת צוֹם כִּפּוּר. מִסִּטְרָא דְּאִמָּא עִלָּאָה אִיהִי צוֹם אֲבָל מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרִיאַת אוּכַל. לֶחֶם אַבִּירִים אָכַל אִישׁ. הַהוּא דְּאִתְּמַר בֵּהּ ה' אִישׁ מִלְחָמָה. וּמָאן הָכָא אִישׁ אֶלָּא דָּא מ' פְּתוּחָה מִלְּגָאו דְּבֵהּ אָכְלוּ אֶת הָמָן מ' שָׁנָה. אֲבָל ם אִיהִי עָלְמָא דְּאָתֵי, לֵית בֵּהּ אֲכִילָה וּשְׁתִיָּה, וְכָל סְפִירָן אִתְקְרִיאוּ צוֹמוֹת בָּהּ. וּבְגִין דָּא קָרְבְּנִין דְּמִתְעַכְּלִין דְּאִנּוּן צְלוֹתִין וּבָעוּתִין אִיהִי שְׁכִינְתָּא תַּתָּאָה. וְהַהוּא דְּאִתְהֲנֵי מִנָּהּ דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, אֹרַח כָּל רֵיחִין דְּקָרְבְּנִין וְקָרִיב לוֹן לְגַבֵּי אַבָּא וְאִמָּא. הָדָא הוּא דִּכְתִיב (בראשית ח) וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ, לֹא כְּתִיב אֶלָּא אֶת רֵיחַ הַנִּיחוֹחַ דָּא אִיהִי. שׁוֹשַׁנָּה רֵיחָא טָבָא לְגַבֵּי אַבָּא וְאִמָּא. שׁוֹשַׁנָּה וַדַּאי בְּחָמֵשׁ עָלִין אִיהִי ה'. אֲבָל רֵיחָא דִּילָהּ ו' דְּאִיהוּ רֵיחָא לָא שַׁרְיָא בֵּהּ עַד דְּאִתְפַּתְּחַת לְסָלְקָא מִנָּהּ רֵיחָא טָבָא. כַּד יִשְׂרָאֵל פָּתְחִין בִּתְיוּבְתָּא שׁוֹשַׁנָּה אִתְפַּתְּחַת לְגַבֵּי בַּעְלָהּ דְּאִיהוּ רֵיחַ דִּילָהּ, וְהַהוּא רֵיחָא סָלִיק לְגַבֵּי אַבָּא וְאִמָּא דְּאִנּוּן יָ'הּ, וַיָּרַח ה' אֶת רֵיחַ. (שם) וַיֹּאמֶר ה' אֶל לִבּוֹ. וַיֹּאמֶר ה' דָּא אַבָּא. אֶל לִבּוֹ דָּא אִמָּא דְּאִתְּמַר בָּהּ לֵב מֵבִין. דִּבְזִמְנָא דְּיִשְׂרָאֵל אִנּוּן חֲטָאָן לַאֲבוּהוֹן דִּי בִּשְׁמַיָּא, אִתְּמַר וַיִּתְעַצֵּב אֶל לִבּוֹ. וּבְזִמְנָא דִּמְהַנְיָן יִשְׂרָאֵל לַאֲבוּהוֹן דִּי בִּשְׁמַיָּא בְּקָרְבְּנִין דִּצְלוֹתָא, כמד\"א (במדבר כח) צַו אֶת בְּנֵי יִשְׂרָאֵל ואָמַרְתָּ לָהֶם אֶת קָרְבָּנִי לַחְמִי וְגוֹ'. מִיָּד שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְגַרְמִין בְּהַהוּא רוּחָא לְאַרְקָא מִשְׁחָא וּנְבִיעוּ מִלְּעֵלָּא בִּשְׁכִינְתֵּהּ הָדָא הוּא דִּכְתִיב (שיר א) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךָ עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. מַאי עֲלָמוֹת. חַ\"י עָלְמִין דִּכְלִילָן בְּחַ\"י עָלְמִין דְּאִתְּמַר בְּהוֹן רֶכֶב אֱלֹהִים רִבּוֹתַיִם אַלְפֵי שִׁנְאָן\"אַדְּהָכֵי הָא סָבָא אִזְדְּמַן לְגַבֵּהּ פָּתַח וְאָמַר מַאי רֶכֶ'ב. אָמַר לוֹ ר' אִיהוּ חָכְמָה רֵאשִׁית חָכְמָה. ב' בִּינָה כ' כֶּתֶר עִלָּאָה. אִנּוּן רֶכֶ'ב לְהַהוּא טָמִיר וְגָנִיז דְּרָכִיב עָלַיְהוּ. וְאִלֵּין תְּלָת סְפִירָן אִנּוּן רָכְבִין עַל חַ\"י עָלְמִין דְּאִנּוּן תֵּשַׁע נְקֻדּוֹת כְּפוּלוֹת וְאִנּוּן אָדָם עִלָּאָה טָמִיר וְגָנִיז בְּטַעֲמֵי דְּאָדָם דִּלְתַתָּא דְּאִנּוּן תֵּשַׁע נִקּוּדִין, אִנּוּן חַ\"י עָלְמִין דְּשָׁט בְּהוּ עִלַּת הָעִלּוֹת, דְּאִיהוּ אָדָם תְּלִיתָאָה דְּלָא אִתְגַּלְּיָא בְּאוֹרַיְתָא וְשָׁט בְּהוּ וְאִנּוּן מֶרְכָּבָה לֵהּ. וְהַאי חַ\"י בָּאָן סָלִיק בויר\"ח. וּבְגִינֵהּ אִתְּמַר וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ. וְכַד יִשְׂרָאֵל סָלְקִין בִּרְכָּאן בִּצְלוֹתִין לְגַבֵּהּ כַּדְקָא יָאוּת, מִיָּד אִתְהַנֵּי מִתַּמָּן. מַה כְּתִיב וַיֹּאמֶר ה' אֶל לִבּוֹ. עכ\"מ.</p>"],[9514015393,"<p>תִּקּוּנִים</p>"],[9514015394,"<p>וְהַמַּשְׂכִילִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר בְּטֶרֶם אֶצָּרְךָ בַּבֶּטֶן יְדַעְתִּיךָ הָדָא הוּא דִּכְתִיב אֲשֶׁר קֹדֶשׁ יְדִיד מִבֶּטֶן. בְּטֶרֶם אֶצָּרְךָ דָּא רוּחַ דִּיצִירָה. וּבְטֶרֶם תֵצֵא מֵרֶחֶם דָּא נֶפֶשׁ דַּעֲשִׂיָּה. נָבִיא לַגּוֹיִם נְתַתִּיךָ דָּא נִשְׁמְתָא. דְּקֹדֶם דְּיֵיתֵי לְעָלְמָא בַּר נָשׁ אִשְׁתְּמוֹדַע לְרוּחֵהּ וְנִשְׁמָתֵהּ וְגוּפֵהּ דְּמִתְחַבְּרָן לְעֵלָּא. וּבְגִין דָּא וַיֹּאמֶר ה' אֶל אַבְרָם, דָּא נִשְׁמְתָא דְּאִיהִי אָב לְרוּחָא וְנַפְשָׁא וְרָם לְגוּפָא. וְעַל אִלֵּין רוּחָא וְנַפְשָׁא וְגוּפָא עָלַיְהוּ אִתְּמַר הֵן כָּל אֵלֶּה יִפְעַל אֵל וְגוֹ' נִשְׁמְתָא, דָּא גּוּף פְּלוֹנִי. לֶךְ לְךָ מֵאַרְצְךָ דָּא שִׁנּוּי מָקוֹם. וּמִמּוֹלָדְתֶךָ דָּא שִׁנּוּי הַשֵּׁם. וּמִבֵּית אָבִיךָ דָּא שִׁנּוּי מַעֲשֶׂה. שִׁנּוּי מָקוֹם דָּא גִּלְגּוּלָא קַדְמָאָה, דְּאִתְעֲקָר מֵאַתְרֵהּ וְאִתְנְטַע בְּגוּפָא אָחֳרָא. וּמָאן גָּרִים לֵהּ הַאי בְּגִין דְּאַעֲקַר אַרְעָא קַדִּישָׁא מֵאַתְרֵהּ דְּהִיא שְׁכִינְתָּא. כמ\"ד וּבְפִשְׁעֲכֶם שֻׁלְּחָה אִמְּכֶם. וּמִמּוֹלַדְתֶּךָ הָכָא רָזָא וּמוֹלָדְתְּךָ אֲשֶׁר הוֹלַדְתָּ אֲחֵרִים לְךָ יִהְיוּ וּבוֹ יִקָּרְאוּ בְּנַחֲלָתָם. בְּגִין דְּלָא יִכָּרֵת שֵׁם הַמֵּת יִקָּרֵא עַל שֵׁם אָחִיו. וְדָא שִׁנּוּי הַשֵּׁם. וּמָאן גָּרִים דָּא בְּגִין דְּאַעֲקַר אִילָנָא דְּאִיהוּ עֵץ הַגַּן מֵאַתְרֵהּ, הָכֵי אִתְעֲקָר מִנֵּהּ וְאִתְקְרֵי עָקָר בְּלֹא בֵּן, עַל שֵׁם דַּעֲקִיר אִיהוּ ו' י' כָּלִיל שִׁית סִטְרִין מֵאַתְרֵהּ. וּמִבֵּית אָבִיךָ דָּא שִׁנּוּי מַעֲשֶׂה. וּמָאן גָּרִים לֵהּ הַאי בְּגִין דְּחָב בְּמַעֲשֶׂה, דְּאִיהִי אִמָּא עִלָּאָה מַעֲשֵׂה בְּרֵאשִׁית, דְּתַמָּן מַחֲשָׁבָה גְּנִיזָא דְּלֵית עֲשִׂיָּה בְּלֹא מַחֲשָׁבָה. הָדָא הוּא דִּכְתִיב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָ, דָּא גּוֹלָפָא. כְּפוּם דְּאִיהוּ מְחֻיָּב בְּחוֹבִין, הָכֵי אִתְנְטַע בֵּהּ וְאִתְרְכִיב עַד דְּאַחְזַר מַה דְּאַעֲקַ'ר לְאַתְרֵהּ. קָם עַמּוּדָא בָּתַר טולא דְּרִבִּי שִׁמְעוֹן וְאָמַר, רִבִּי רִבִּי רָזָא דָּא רָזָא אָחֳרָא עִלָּאָה אִית בְּגִלְגּוּלָא לְעֵלָּא בְּדַרְגִּין עִלָּאִין. וְדָא אִיהוּ וַיֹּאמֶר יְיָ אֶל אַבְרָם. דָּא אִיהוּ דְּאִתְּמַר בֵּהּ הֲלֹא אָב אֶחָד לְכֻלָּנוּ. וּמָאן אָמַר לוֹ הַהוּא רָם דְּעָלֵהּ דְּאִיהוּ רָם עַל כָּל גְּבוֹהִים. וּמָה אָמַר לוֹ לֵךְ תְּרֵין תֵּירוּכִין אִנּוּן י' י' מִן א אָת ו' מִתַּמָּן תָּרִיךְ לֵהּ, הַהוּא רָם עַל כָּל רָמִים, דְּאִיהוּ עִלַּת עַל כָּל עִלָּאִין. וּלְאָן שָׁלַח לֵהּ, אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ, דָּא שְׁכִינְתָּא תַּתָּאָה. אָמַר לוֹ רִבִּי שִׁמְעוֹן אִי הָכֵי מַאי מֵאַרְצְךָ וּמִמּוֹלַדְתֶּךָ. אָמַר לוֹ רִבִּי רִבִּי תְּלָת אַלְפִין אִנּוּן מִתְּלָת שְׁמָהָן דְּאִנּוּן אֶהְיֶ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה דְּאִתְּמַר לְמֹשֶׁה עָלַיְהוּ דְּאִיהוּ דִּיּוֹקְנָא דְּהַהוּא ו' עִלָּאָה. וַיֹּאמֶר ה' אֶל מֹשֶׁה אֶהְיֶה אֲשֶׁר אֶהְיֶה. אֶהְיֶה שְׁלָחַנִי אֲלֵיכֶם. הָכָא אִתְרְמִיז דְּאִתְתְּרַךְ מִתְּלָת אִלֵּין, דְּאִנּוּן תְּלָת עָלְמִין דְּאִתְּמַר בְּהוֹן מֵאַרְצְךָ וּמִמּוֹלַדְתֶּךָ וּמִבֵּית אָבִיךָ (בראשית). וְדָא אִיהִי אִמָּא עִלָּאָה דְּאִיהִי כֶּתֶר אֵם כָּל חַי. דְּאָת ו' בִּמְעָהָא אִיהִי אֵ בְּכֶתֶר עִלָּאָה. וא תִּנְיָנָא בְּבִינָא וְאִיהִי אֶלֶ\"ף תְּלִיתָאָה בְּאֶמְצָעִיתָא דְּאָת ו'. וְרָזָא דְּמִלָּה יוּ\"ד הֵ\"א וָא\"ו הֵ\"א וְאִיהִי כֶּתֶר מַלְכוּת. אֶל הָאָרֶץ דָּא שְׁכִינְתָּא תַּתָּאָה דִּכְלִילָן בֵהּ כֻּלְּהוּ. וְאֶעֶשְׂךָ לְגוֹי גָּדוֹל וַאֲבָרֶכְךָ מִסִּטְרָא דָּא עִלָּאָה. וַאֲגַדְּלָה שְׁמֶךָ מִסִּטְרָא דָּא תִּנְיָנָא. וֶהְיֵה בְּרָכָה מִסִּטְרָא דָּא תְּלִיתָאָה.</p>"],[9514015395,"<p>וַיְהִי רָעָב בָּאָרֶץ וַיֵּרֶד אַבְרָם מִצְרַיְמָה, דַּע כִּי לִבָּא אִיהוּ דִּיּוּרָא דְּנִשְׁמְתָא וְאִיהוּ שִׁבְעָה שֶׁנֶּאֱמַר אֶרֶץ אֲשֶׁר לֹא בְּמִסְכְּנוֹת תֹּאכַל בָּהּ לֶחֶם לֹא תֶּחְסָר כֹּל בָּהּ. וְכַד נַחְתָּא נִשְׁמְתָא לִטְחוֹל דְּאִיהוּ רָעָב, בְּגִין דִּכְבָר לָא יָהִיב לֵהּ מִדָּמָא אֶלָּא שִׁיּוּרִין בִּישִׁין דִּילֵהּ וּבְגִין דָּא (בראשית י״ב:י׳) כִּי כָּבֵד הָרָעָב בָּאָרֶץ. בְּהַהוּא זִמְנָא דְּנַחְתַת תַּמָּן נִשְׁמְתָא דְּחִילַת מִתַּמָּן, שֶׁנֶּאֱמַר וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבֹא מִצְרַיְמָה, קֹדֶם דְּאִתְקְרַב תַּמָּן נִשְׁמְתָא. וַיֹּאמֶר אֶל שָׂרָה אִשְׁתּוֹ, דָּא גּוּפָא וּמָה אָמַר לָהּ הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אַתְּ. אַתְּ שַׁפִּירָא בְּזִכְוָן. וּבְגִינָךְ אֲנָא דָּחִיל דְּקָטְלִין לִי בְּגִינָךְ, דְּצוֹפֶה רָשָׁע לַצַּדִּיק, וּבְגִין דָּא עָרוּם רָאָה רָעָה וְנִסְתָּר. דְּזַכָּאָה דְּאִשְׁתְּכַח בֵּין חַיָּבַיָּא אִתְּפַס בֵּינַיְהוּ. וּבְגִין דָּא וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִּצְרִים, וְרָזָא דָּא כָּל הַבֵּן הַיִּלּוֹד. וּבְגִין דָּא וְהָרְגוּ אוֹתִי וְאוֹתָךְ יְחַיּוּ. אֶלָּא אָמְרֵי נָא אֲחֹתִי אַתְּ. הָדָא הוּא דִּכְתִיב אֱמֹר לַחָכְמָה אֲחֹתִי אַתְּ. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ, בְּהַאי עָלְמָא. וְהָיְתָה נַפְשִׁי בִּגְלָלֵךְ לְעָלְמָא דְּאָתֵי:</p>"],[9514015396,"<p>אַדְּהָכֵי הָא עַמּוּדָא דִּנְהוֹרָא דְּאִתְחַזְּיָא בטול' דְּרִבִּי שִׁמְעוֹן וא\"ל. רִבִּי רִבִּי הָכָא רָזָא וְלֹא צָרִיךְ לְאִתְכַּסְּיָא. בְּגִין מָארֵי חוֹבִין אַחֲזֵי קֳדָמַיְהוּ מָארֵי דְּעוּתְרָא דְּלֹא קַטְלִין לֵהּ עַל מָמוֹנֵהּ. וּמַאי מָמוֹנָא דִּילֵהּ בַּיִת וְהוֹן נַחֲלַת אָבוֹת וְגוֹ'. וְדָא בַּת עַיִן דְּאִתְּמַר בָּהּ כְּסוּת עֵינַיִם דְּצָרִיךְ לְאִתְכַּסָּאָה בֵּינִי חַיָּבַיָּא, בְּגִין הַהוּא אוֹר דְּנָהִיר בָּהּ, דְּאִיהוּ בַּעְלָהּ דְּאִיהוּ רָז צָרִיךְ לְכַסָּאָה לֵהּ מִבֵּינַיְהוּ דְּלֹא אִתְפַּס עָלֵהּ. בְּגִין דַּחֲשׁוֹכָא דְּאִיהוּ נָחָשׁ הַקַּדְמוֹנִי מְקַנֵּא עַל נְהוֹרָא דְּאִיהוּ אוֹר הַגָּנוּז, דְּאִתְּמַר בֵּהּ וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא וַתִּצְפְּנֵהוּ (שמות). וְהָכֵי מָאן דְּאִתְגְּלֵי לֵהּ אוֹר דְּאִיהוּ רָ'ז בֵּין חַיָּבַיָּא. צָרִיךְ לְכַסָּאָה לֵהּ עַד דְּיֵיתוּן צַדִּיקַיָּא לְאַנְהֲרָא בֵּינַיְהוּ. הָדָא הוּא דִּכְתִיב אוֹר זָרֻעַ לַצַּדִּיק. וְאִי לָא טָמִיר לֵהּ מַה כְּתִיב (בראשית י״ב:ט״ו) וַיְהִי כְּבֹא אַבְרָם מִצְרַיְמָה, וַיְהַלְלוּ אֹתָהּ אֶל פַּרְעֹה וַתֻּקַּח הָאִשָּׁה בֵּית פַּרְעֹה:</p>"],[9514015397,"<p>פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר וַי לִבְנֵי עָלְמָא דְּאִנּוּן אֲטִימִין לִבָּא וסְתִימִין עַיְנִין. דְּהָא כְּמָה רָזִין סְתִימִין אִית בְּאוֹרַיְתָא וְלֹא מַשְׁגִּיחִין בְּהוֹן. דְּלֹא בָּעָאן אֶלָּא לְמֵיכַל תֶּבֶן דְּאוֹרַיְתָא, דְּאִיהוּ פָּשַׁט לְבוּשָׁא דְּאוֹרַיְתָא, וְלֹא טַעֲמִין מִן מֹחָא מִלְּגָאו. תָּא חֲזֵי אִית נִשְׁמְתָא דְּאִיהוּ גּוּפָא לנִשְׁמְתָא. וְאִית נִשְׁמְתָא לְנִשְׁמְתָא. וְאִית נִשְׁמְתָא דְּכוּרָא דְּאִתְקְרִיאַת אַבְרָם. וְאִית נִשְׁמְתָא נוּקְבָא דְּאִתְקְרִיאַת שָׂרַי. ואַף עַל גַּב דְּאִתְקְרִיאַת דְּכוּרָא, הַאי נִשְׁמְתָא אַבְרָם בְּלֹא ה' טָפֵל אִיהוּ לנִשְׁמְתָא דְּאִיהִי שָׂרַי נוּקְבָא, דְּתַמָּן י' אוֹ לְשָׂרָה דְּתַמָּן ה'. וּבְגִין דָּא אוֹקְמוּהּ מָארֵי מַתְנִיתִין דְּטָפֵל הֲוָה אַבְרָם לְשָׂרָה בַּנְּבוּאָה, בְּגִין דְּאִיהִי זָכְתָה לִתְרֵין אַתְוָן, י' בְּקַדְמִיתָא שָׂרַי וּלְבַסּוֹף שָׂרָה בְּה'. כַּד הֲוַת בְּיוּ\"ד הֲוַת יְחִידָא. וְכַד זָכְתָה בְּה' אִתְקְרִיאַת אִימָּא. וְכַד הֲוַת יָחִיד' בְּיוּ\"ד עָלַהּ אִתְּמַר שָׁמְרֵנִי כְּאִישׁוֹן בַּת עַיִן. וּפַרְעֹה דְּאִיהוּ דִּיּוֹקְנָא דְּנָחָשׁ חַיָּבָא, כֶּתֶר דִּשְׁבָחוּהָ כְּתִיב וַתֻּקַּח הָאִשָּׁה בַּיִת פַּרְעֹה. וְדָא רָמִיז לְגָלוּתָא דְּמִצְרַיִם דְּגָלְתָא שְׁכִינָה בְּמִצְרַיִם. וְנָחָשׁ בָּעָא לקרב' לָהּ. מַה כְּתִיב וְהַזָּר הַקָּרֵב יוּמָת. וַיְנַגַּע ה' אֶת פַּרְעֹה. וְדָא רָמִיז לִמְחָאָן דְּמֹחָא קוּדְשָׁא בְּרִיךְ הוּא לְפַרְעֹה וּלְמִצְרַיִם וְלִמְמָנָן דִּילְהוֹן. וּמַה כְּתִיב וְעַתָּה הִנֵּה אִשְׁתְּךָ קַח וָלֵךְ. כְּגַוְנָא דְּפַרְעֹה בְּמִצְרַיִם דְּאָמַר לְמֹשֶׁה וּלְיִשְׂרָאֵל שַׁלַּח מֵעַל פָּנַי וְיֵצֵאוּ. וְהַאי אִיהִי אַבְטָחוּתָא לְיִשְׂרָאֵל ולִשְׁכִינְתָּא בְּגָלוּתָא בַּתְרָאָה. מִיָּד דְּיִבְעוּן אֻמִּין פָּלְחֵי כּוֹכְבַיָּא דְּעָלְמָא לְקָרְבָא לְגַבָּהּ וּלְדַחֲקָא לָהּ, אַגְרָא דְּכַלָּה דּוֹחֲקָא. כְּתִיב וַיְנַגַּע ה' אֶת פַּרְעֹה. מִיָּד וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים. דְּעַל שְׁכִינְתָּא אִתְּמַר אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. וְהַזָּר הַקָּרֵב לְגַבָּהּ יוּמָת. וּכְמָה דְּפַרְעֹה קַדְמָאָה אָמַר הִנֵּה אִשְׁתְּךָ קַח וָלֵךְ, הָכֵי אָמַר פַּרְעֹה קוּמוּ צְאוּ מִתּוֹךְ עַמֵּי, וְכָךְ עֲתִידִין עֲמָמִין דְּעָלְמָא לְמֵימַר לְיִשְׂרָאֵל קוּמוּ צְאוּ, פּוּקוּ מִבֵּינָנָא וְקוּדְשָׁא בְּרִיךְ הוּא לֹא אַפִּיק לוֹן מִבֵּינַיְהוּ עַד דְּנָטִיל מְמָנֵהּ. וְכַמָּה דְּאִתְּמַר וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים וַיְשַׁלְּחוּ אוֹתוֹ וְאֶת אִשְׁתּוֹ וְאֶת כָּל אֲשֶׁר לוֹ. כְּגַוְנָא דָּא בְּגָלוּתָא בַּתְרָאָה הָדָא הוּא דִּכְתִיב וַהֲבִיאוּ אֶת כָּל אַחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגוֹ'. אַדְּהָכֵי הָא אֵלִיָּהוּ אִזְדְּמַן לְגַבֵּהּ וְאָמַר רִבִּי רִבִּי וַדַּאי כְּגַוְנָא דָּא אִיהוּ בנִשְׁמְתָא (דא איהי נשמתא) אִיהִי מִסִּטְרָא דִּשְׁכִינְתָּא. וְיֵצֶר הָרָע בָּעֵי לִקְרָבָא לְגַבָּהּ וְקוּדְשָׁא בְּרִיךְ הוּא מָחֵי לָהּ בְּכַמָּה מַכְתְּשִׁין, כְּגַוְנָא דְּמָחָא לְפַרְעֹה עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. וּבְהַהוּא זִמְנָא נָחִית סַמָּאֵל וְכָל חַיָּלָיו לְהַהִיא נִשְׁמְתָא, וְנָטִיר לָהּ עַד דְּאִתְקְרֵיבת לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְהָכֵי כְּגַוְנָא דָּא כָּל בַּר נָשׁ דְּבָעֵי לְקָרְבָא לְצַדִּיק לאוזפא לֵהּ, קוּדְשָׁא בְּרִיךְ הוּא מָחֵי לֵהּ בְּכַמָּה מַכְתְּשִׁין לְאַנַּזְקָא עַד דְּיִתְחַזַּר לְשִׁעְבּוּדֵהּ. וּבְגִין דָּא אָמְרָה אִנְתּוּ לְהָמָן חַיָּבָא (אסתר ו) אִם מִזֶּרַע הַיְּהוּדִים מָרְדְּכַי לֹא תּוּכַל לוֹ כִּי נָפוֹל תִּפֹּל לְפָנָיו. אֲבָל נִשְׁמְתָא דְּלָאו אִיהוּ מִסִּטְרָא דְּרוּחָא דְּקֻדְשָׁא, אִית לָהּ לְאִסְתַּמְּרָא, דְּאִית לֵהּ רְשׁוּ לִמְקַטְרְגָא עָלֵהּ, וְעָרוּם רָאָה רָעָה וְנִסְתָּר.</p>"],[9514015398,"<p>וַיַּעַל אַבְרָם מִמִּצְרַיִם מַאי וַיַּעַל אַבְרָם מִמִּצְרַיִם. אָמַר לוֹ אֵלִיָּהוּ וַדַּאי בְּזִמְנָא דְּנִשְׁמְתָא אשתזיבה מֵהַהוּא מְמָנָא בִּישָׁא, דְּאִיהוּ אֵל אַחֵר מֶלֶךְ מִצְרַיִם מַלְכָּא דְּאִנּוּן צוֹרְרִים דְּדַחֲקִין לְנִשְׁמָתִין, וְאִנּוּן מַלְאֲכֵי חַבָּלָה מַזִּיקִין כְּמָא דְּאוֹקְמוּהּ מָארֵי מַתְנִיתִין, נִשְׁמָתִין דְּרַשִּׁיעַיָּא הֵן הֵן הַמַּזִּיקִין בָּעוֹלָם. מַה כְּתִיב בְּמָארֵי נִשְׁמְתָא וַיַּעַל אַבְרָם מִמִּצְרַיִם. אִסְתְּלַק עָלַיְהוּ בְּתֻקְפָּא סַגֵּי הוּא וְנִשְׁמָתֵהּ וְכָל דִּילֵהּ. וַאֲפִלּוּ לוֹט עִמֵּהּ דְּאִיהוּ שַׂר מִסִּטְרָא דִּימִינָא, דְּלָאו כָּל שִׁירִין שַׁוְיָן, דְּאִית שֵׁדִין דְּאִנּוּן כְּגַוְנָא דְּמַלְאָכִין קַדִּישִׁין, דְּיָדְעִין מַה דַּהֲוָה וּמַה דְּעָתִיד לְמֶהֱוֵי. וְעַל הַאי שֵׁד אָמַר קוּדְשָׁא בְּרִיךְ הוּא אֶעֱשֶׂה לוֹ עֵזְר. אִם זָכָה עֵזְר. וְאִם לָאו אִיהוּ כְּנֶגְדּוֹ שֵׁד. הָדָא הוּא דִּכְתִיב (בראשית י״ג:ו׳) וְלֹא נָשָׁא אוֹתָם הָאָרֶץ לָשֶׁבֶת יַחְדָּיו. וְעוֹד אִי זָכָה בַּר נָשׁ אִיהוּ עֵזְר, אֵימָתַי בְּלֵיל שַׁבָּת דְּאוֹזְפִין תַּקִּין מַלְאָכִין לבַּר נָשׁ, דָּא יֵצֶר הַטוֹב וְדָא יֵצֶר הָרָע. אִי זָכָה יֵצֶר הַטוֹב מְבָרֵךְ לְבַעַל הַבַּיִת וּלְאִנְתְּתֵהּ וְכָל דִּילֵהּ, וְיֵצֶר הָרָע אִיהוּ עוֹזֵר לֵהּ בְּעַל כָּרְחֵהּ וְעוֹנֶה אָמֵן. וְאִי לָאו אִיהוּ כְּנֶגְדּוֹ, ולייט לֵהּ וּלְכָל דִּילֵהּ. וּבְגִין דָּא אִתְקְרֵי לוֹט דְּאַיְתֵי לְוָטִין עַל הַהוּא בַּר נָשׁ וְעַל בֵּיתֵהּ, וְאִיהוּ אָעִיל קְטָטָה בְּבֵיתֵהּ. הָדָא הוּא דִּכְתִיב וַיְהִי רִיב בֵּין רוֹעֵי מִקְנֵה אַבְרָם וּבֵין רוֹעֵי מִקְנֵה לוֹט. וּבְהַהוּא זִמְנָא (בראשית י״ג:ח׳) וַיֹּאמֶר אַבְרָם אֶל לוֹט אַל נָא תְּהִי מְרִיבָה בֵּינִי וּבֵינֶיךָ וְגוֹ' כִּי אֲנָשִׁים אַחִים אֲנַחְנוּ. מִסִּטְרָא דְּאִיהִי גּוּפָא וּמָה אָמַר לוֹ הֲלֹא כָּל הָאָרֶץ לְפָנֶיךְ (שם). וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין אִם רָאִיתָ שֶׁיֵּצֶר הָרָע מִתְגַּבֵּר עָלֶיךָ הוֹלִיכֵהוּ לְבֵית הַמִּדְרָשׁ. אִם אֶבֶן הוּא נִמּוֹחַ וְאִם בַּרְזֶל מִתְפּוֹצֵץ. אָמַר רִבִּי שִׁמְעוֹן לְאֵלִיָּהוּ דָּא יַנּוּקֵי יָדְעֵי לֵהּ. אָמַר לֵהּ רִבִּי רִבִּי, וַדַּאי הָכֵי הוּא, אֲבָל רָזָא דְּמִלֵּי דְּפָרָשָׁתָא דָּא, לָאו אִנּוּן לְגַלָּאָה הָכֵי אֶלָּא בֵּינִי וּבֵינֶיךָ:</p>"],[9514015399,"<p>פָּתַח וְאָמַר (בראשית י״ב:י׳) וַיְהִי רָעָב בָּאָרֶץ. מַאי רָעָב הָכָא. אֶלָּא וַדַּאי כַּר אִסְתְּלַק נְבִיעוּ מֵאַרְעָא דִּשְׁכִינְתָּא, מִיָּד כְּתִיב וַיְהִי רָעָב בָּאָרֶץ (שם). וַיֵּרֶד אַבְרָם מִצְרַיְמָה, נָחִית קוּדְשָׁא בְּרִיךְ הוּא לְדַיְּרָא בֵּין סִטְרִין בִּישִׁין אִלֵּין, בְּגִין זַרְעָא דִּילֵהּ לְמֶהֱוֵי נָטִיר בֵּינַיְהוּ. אָמַר לוֹ רִבִּי שִׁמְעוֹן רִבִּי רִבִּי וְהָא כְּתִיב בִּשְׁכִינְתָּא אֶרֶץ אֲשֶׁר לֹא בַּמִּסְכְּנוֹת תֹּאכַל בָּהּ לֶחֶם. אָמַר לוֹ וַדַּאי הָכֵי הוּא. דִּבְזִמְנָא דְּיִשְׂרָאֵל נָטְרִין אוֹת בְּרִית, אִתְמְלִיאַת כָּל טוֹב וְלֹא חָסֵר מִנַּהּ, וְאִתְּמַר בָּהּ וַתֵּרָאֶה הַיַּבָּשָׁה. וּבְהַהוּא זִמְנָא אִי לָא נָחִית קוּדְשָׁא בְּרִיךְ הוּא לנטר' לָהּ, אִית רְשׁוּת לְסִטְרִין אָחֳרָנִין לִקְרָבָא תַּמָּן. וְהַהוּא דְּגָרִים דָּא אִית רְשׁוּ לִמְקַטְרְגָא לְקַטְלָא לֵהּ. בְּגִין דָּא אָמַר לֵהּ וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִּצְרַיִם וְגוֹ' (שם). וְעַל דָּא אָמְרֵי נָא אֲחֹתִי אַתְּ (שם) לֹא תִּשְתְּמוֹדַע בֵּינַיְהוּ. וְאִי תֵּימָא מָה חָב אַבְרָם. אֶלָּא חוֹבָה דִּילֵהּ קֹדֶם דְּאַיְתֵי לְעָלְמָא, הֲוָה בְּאוֹת ה' בְּחֶסְרוֹנָא דִּילֵהּ תַּמָּן הֲוָה. וּבְגִין דָּא הֲוָה אִתְקָרֵי אַבְרָם בְּלֹא ה' עַד דְּזָכָה לָהּ וּבֵהּ אִשְׁתְּלִים בְּכָל אֶבְרוֹהִי. וּבְגִין יוּד דַּהֲוָה בְּשָׂרַי אָמַר אָמְרֵי נָא אֲחֹתִי אַתְּ לְאַגָּנָא. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ (שם) בַּת יְחִידָאָה. וְאִתְּמַר בָּהּ אֶבֶן מָאֲסוּ הַבּוֹנִים. יִיטַב לִי מִסִּטְרָא דְּטוֹב. וְחָיְתָה נַפְשִׁי מִסִּטְרָא דְּחַי עָלְמִין. בְּגִיָהּ דִּתְרֵין דַּרְגִּין אִלֵּין תִּבְנָא בְּהוֹן עַמּוּדָא דְּאֶמְצָעִיתָא וְצַדִּיק:</p>"],[9514015400,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה וְגוֹ'. פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר דְּמִיכִין דְּחֶבְרוֹן קוּמוּ. וְיִהְיוּ חַיֵּי שָׂרָה, מָאן שָׂרָה הָכָא. דָּא שְׁכִינְתָּא עִלָּאָה. בְּגִין דְּשָׂרָה דִּלְתַתָּא בְּצַדִּיק וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. הָכֵי צַדֶּקֶת דָּא אִתְבְּרִיאַת בְּדִיּוֹקְנֵהּ דִּשְׁכִינְתָּא. וְיִהְיוּ חַיֵּי שָׂרָה דָּא שְׁכִינְתָּא. וּמַאי נִיהוּ חַיִּים דִּילֵהּ יָ\"הּ וְדָא הַהוּא שְׁכִינָה. שָׁכֵן יָ\"הּ, וְהַאי אִיהוּ חַיִּים דְּנִשְׁמְתָא הָדָא הוּא דִּכְתִיב כָּל הַנְּשָׁמָה תְּהַלֵּל יָ'הּ. וְהַאי ה' בא\"ת ב\"ש צ'. עִם י' סָלִיק לק'. וְאִנּוּן מֵאָה בִּרְכָּאן דְּחַיָּב בַּר נָשׁ לְאַרְקָא בְּכָל יוֹמָא לִשְׁכִינְתָּא וְדָא אִיהוּ מֵאָה שָׁנָה. וְעָלַיְהוּ מָנֵי קוּדְשָׁא בְּרִיךְ הוּא לבַּר נָשׁ מָה ה' אֱלֹהֶיךָ שׁוֹאֵל מֵעִמָּךְ, א\"ת מָ\"ה אֶלָּא מא\"ה. וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים אִלֵּין עֶשֶׂר אֲמִירָן וְעֶשֶׂר דִּבְּרוֹת וְשֶׁבַע יוֹמִין קַדְמָאִין דְּעוֹבָדָא דִּבְרֵאשִׁית וְשֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה וְיוֹם הַשַּׁבָּת דְּאִיהוּ וַיְכֻלּוּ כְּלָלָא דְּכֻלְּהוּ. וְלָקָבְלַיְהוּ אִתְיְהִיבַת אוֹרַיְתָא בְּעֶשְׂרִים וְשֶׁבַע אַתְוָן, כ'ב דְּאוֹרַיְתָא וְחָמֵשׁ דְּאִנּוּן מַנְצְפַּ\"ךְ דְּצוֹפִין אֲמָרוּם. וְאִם ח\"ו עַבְרִין עָלַיְהוּ יִשְׂרָאֵל מִתְבַּדְּרִין לְאַרְבַּע סִטְרִין, וּשְׁכִינְתָּא גָּלְתָא עִמְּהוֹן הָדָא הוּא דִּכְתִיב וַתָּמָת שָׂרָה. מִיתָה דִּילֵהּ דְּאִסְתְּלַק יָ'הּ מִנַּהּ וְאִשְׁתְּאָרַת כֵּ'ס חָסֵר. וּבְגִין דָּא וַיֹּאמֶר כִּי יָד עַל כֵּ'ס יָ'הּ. בְּקִרְיַת אַרְבַּע אִלֵּין ד' סִטְרִין דְּאִתְבַּדְּרַת עַם יִשְׂרָאֵל וּבְגִין דָּא תַּקִּינוּ בִּצְלוֹתָא וְקַבְּצֵנוּ יַחַד מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ. דְּגָלוּתָא אִיהִי מִיתָה לִשְׁכִינְתָּא וּלְכָל יִשְׂרָאֵל בְּנָהָא. וְעוֹד וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע, אִלֵּין תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וּתְהוֹם דְּאִיהִי אִתְלְבִישַׁת בְּאַרְעָא דְּאִתְּמַר בָּהּ וְהָאָרֶץ הָיְתָה תֹהוּ וְגוֹ' (שם). מַשְׁכְּנָא צַדִּיק דְּלֵית בָּהּ נְבִיעוּ דְּאוֹרַיְתָא. מֵאַרְבַּע חֵיוָן דִּילֵהּ דְּאִנּוּן אַרְבַּע חַיּוֹת הַכִּסֵּא, גָּלוּ בְּאַרְבַּע יְסוֹדִין אֵלּוּ דְּאִנּוּן תֹּהוּ קַו יָרֹק, קְלִפָּה יְרֻקָּה דֶּאֱגוֹזָא. בְּהוּ גָּוָן חִוָּר קְלִפָּה תִּנְיָנָא, וְחֹשֶׁךְ קְלִפָּה תְּלִיתָאָה דֶּאֱגוֹזָא דְּאִיהוּ אֵשׁ מִתְלַקַּחַת. תְּהוֹם חָלָל דֶּאֱגוֹזָא דְּתַמָּן מֹחָא דְּאִיהִי שְׁכִינְתָּא כֻּרְסֵא יְקָרָא וְאַרְבַּע חֵיוָן דִּילֵהּ. דְּהָכֵי אִתְפְּלַג מֹחָא דֶּאֱגוֹזָא לְאַרְבַּע סִטְרִין דְּעָלַיְהוּ קַיְּמָא מֹחָא. וְאִלֵּין אִנּוּן לָקֳבֵל אַרְבַּע רָהִיטֵי מֹחָא דְּבַר נָשׁ עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּסוֹכְכֵנִי. אִנּוּן אַרְבַּע קְלִפִּין דֶּאֱגוֹזָא דְּאִנּוּן בְּרָזָא דְּעָרְלָה דְּעָלַיְהוּ יּעַשׂ ה' אֱלֹהִים לָאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם (שם). וְאוֹקְמוּהּ קַדְמָאֵי מַאי עוֹר, דָּא מַשְׁכְּנָא דְּחִוְיָא. וּבְזִמְנָא דְּיִשְׂרָאֵל בְּאִנּוּן קְלִפִּין דְּאִנּוּן ד' גָּלֻיּוֹת אִנּוּן בְּפֵרוּדָא כִּבְיָכוֹל כְּאִלּוּ לֹא הָיוּ גּוֹי אֶחָד וּשְׁמֵהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לֹא שַׁרְיָא עָלַיְהוּ וּבְגִין דָּא אוֹקְמוּהּ מָארֵי מַתְנִיתִין כָּל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. אָמַר רִבִּי אֶלְעָזָר אַבָּא וְהָא שְׁמַעְנָא דְּאַתְוָן דִּשְׁמָא קַדִּישָׁא הָכֵי אִנּוּן י' בְּפֵרוּדָא מִן ה' ו', מִן ה' וְלֹא מִתְחַבְּרִין עַד דְּיִשְׂרָאֵל יִפְקוּן מִן גָּלוּתָא. אָמַר לוֹ בָּגְרֵי אִית אַתְוָן דְּאִנּוּן לְבוּשִׁין דְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִתְקְרִיאוּ עַל שְׁמֵהּ דְּאִתְבְּרִיאוּ. הָדָא הוּא דִּכְתִיב כָּל הַנִּקְרָא בִּשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו. וְאִלֵּין בְּפֵרוּדָא. וְכַד אִתְחַבְּרָן בְּמִנְיָנָא תְּלָת עָשָׂר לְעֵלָּא וּתְלָת עָשָׂר לְתַתָּא, וְסָלְקִין עֶשְׂרִין וְשִׁית יְהוָֹ\"ה כְּחֻשְׁבַּן אֶחָ'ד אֶחָ'ד כְּדִכְתִיב בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. אֲבָל אַתְוָן דְּיִחוּדָא בְּאֹרַח אֲצִילוּת, לָאו תַּמָּן חֻשְׁבָּנָא וְלָא פירוְדָא. וּבְגִין דָּא וְנָהָר יֹצֵא מֵעֵדֶן וְגוֹ' וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, בְּזִמְנָא דְּיֵיתֵי פֻּרְקָנָא יִתְקַיִּם וּנְפֻצוֹת יְהוּדָה יְקַבֵּץ מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ:</p>"],[9514015401,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. מֵאָה שָׁנָה דָּא יו\" דְּסָלְקַת לְמֵאָה בִּתְרֵין הֵהִי\"ן כְּגַוְנָא דָּא ה\"י סְלִיקַת יוּ\"ד דְּסָלְקַת לְמֵאָה בִּתְרֵין הֵהִ\"ין כְּגַוְנָא דָּא הֵ\"י סְלִיקַת בְּיוּ\"ד. חָמֵשׁ פַּעֲמַיִם י' הֵם חַמְשִׁין. וְכָךְ ה' הָאַחֶרֶת ןִ' הֲרֵי מֵאָה וְעֶשְׂרִים שָׁנָה דָּא ו' דִּסְלִיקַת לְכ' שֶׁל כֶּתֶר וְנַעֲשֵׂית כ\"ו. בֵּהּ אִשְׁתְּלִים י' לְמֶהֱוֵי י' י' בְּחֻשְׁבָּן כְּגַוְנָא דָּא אֵ' אִיהִי יוּ\"ד לְעֵלָּא ו' בְּאֶמְצָעִיתָא דָּלֶ\"ת לְתַתָּא וּלְזִמְנִין י' לְעֵלָּא י' לְתַתָּא ו' בְּאֶמְצָעִיתָא וּסְלִיקַת לְחֻשְׁבַּן כ\"ו. וְדָא כ\"ו מִן כ'וזו וּבְגִין דכ' אִיהִי כֶּתֶר רַחֲמֵי וְרַעֲוָא דְּלֵית תַּמָּן דִּינָא כְּלָל, אָמְרֵי מ\"מ דִּמְעַשְּׂרִין וּלְמַטָה לֹא מַעֲנִישִׁין בְּעָלְמָא דֵּין. וְשֶׁבַע שְׁנִין דָּא ו' כַּד שַׁרְיָא י' עַל רֵישֵׁהּ אִתְעֲבִיד ז'. וְאִם זָכָה בִּשְׁכִינְתָּא דְּאִיהִי ז' לְנַטְרָא לָהּ בַּבְּרִית, בְּגִין דְּאִיהִי בְּרִית מַמָּשׁ שַׁרְיָא עָלֵהּ ז' דְּאִיהוּ יוֹם שְׁבִיעִי. וְאִתְּמַר בֵּהּ שֶׁבַע בַּיּוֹם הִלַּלְתִּיךָ. וְאִי לָאו כְּתִיב בֵּהּ וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי שֶׁבַע וְעִקָּרָא דְּכֹלָּא אִיהוּ אוֹת בְּרִית דְּבֵהּ זָכֵי לְעָלְמָא דְּאָתֵי, דְּאִיהוּ עוֹלָם הַבָּא דְּאֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה לֹא קִנְאָה וְלֹא תַּחֲרוּת, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם, וְנֶהֱנִים מִזִּיו הַשְּׁכִינָה. וְתִשְׁכַּח סמ\"ך בִּיסוֹד דְּאִיהוּ כ\"ו פָּלִיג סמ\"ך וְתִשְׁכַּח בֵּהּ כ\"ו. וִיסוֹד הוּא יוֹם הַשְּׁבִיעִי וְתִשְׁכַּח בֵּהּ כוז'ו. אָמַר רִבִּי אֶלְעָזָר אַבָּא וְהָא כוז'ו אַשְׁכַּחְנָא, אֲבָל וְ' בַּתְרָאָה לָא אַשְׁכַּחְנָא בֵּהּ בְּאַתְוָן. א\"ל בְּרִי כַּד אָת חָשִׁיב מֵאִמָּא עִלָּאָה אִתְקְרֵי שְׁמֵהּ וְכַד אַתְּ חָשִׁיב מִימִינָא דְּאִיהִי גְּדֻלָּה אִתְקְרֵי ו'. אָמַר לוֹ הַאי שַׁפִּיר. כַּף אִתְחֲשִׁיבַת בִּסְפִירָן ל\"ב הָא אִנּוּן וְלֹא יַתִּיר. כְּמָה דְּאָמְרֵי בְּסֵפֶר יְצִירָה, עֶשֶׂר סְפִירָן בְּלִי מָה עֶשֶׂר וְלֹא תֵּשַׁע, עֶשֶׂר וְלֹא אֶחָד עֶשֶׂר. אָמַר לוֹ בְּרִי כ' אַחֲזֵי י' מֵעֵלָּא לְתַתָּא וּמִתַּתָּא לְעֵלָּא וְכֹלָּא אֵ' דְּאִיהִי רָזָא דְּיוֹ\"ד וְכֹלָּא חַד. וּבְגִין דָּא תִּשְׁכַּח דְּאָת יוּ\"ד אִיהִי כ' כֶּתֶר דְּאָת יוּ\"ד דְּסָלִיק עָלַהּ בְּחֻשְׁבְּנָא וְכֹלָּא חַד. כִּי יְ\"יָ אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. כִּי הוּא י' וְאִיהוּ יְהוָֹ'ה דְּסָלִיק כ\"ו וְעִם וְאַרְבַּע אַתְוָן סָלִיק ל' לְחֻשְׁבַּן כ\"י. וְדָא רָזָא יְהוָֹ'ה.</p>"],[9514015402,"<p>וַתָּמָת שָׂרָה דָּא נִשְׁמְתָא דְּאִתְּמַר בָּהּ וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וּמַאי מִיתָה דִּילָהּ, דְּנַחְתַת מִלְּעֵלָּא וְעָאלַת בְּאַרְבַּע יְסוֹדִין בִּישִׁין דְּאִנּוּן אֵשׁ רוּחַ מַיִם עָפָר וְאִנּוּן שִׁתּוּפָא דְּנַפְשָׁא דִבְעִירָא, בְּגִין דְּאִיהוּ תַּמָּן בְּלֹא אוֹרַיְתָא. דְּקֹדֶם דְּנִשְׁמְתָא נַחְתָּא בְּגוּפָא בְּד' יְסוֹדִין אִלֵּין אִתְיְהִיבַת אוֹרַיְתָא כֻּלָּהּ. וּמִיָּד דְּעָאלָת בְּגוּפָא אִסְתַּלְּקַת מִנֵּהּ. וְרָזָא דְּמִלָּה אֲנִי מְלֵאָה הָלַכְתִּי וְרֵיקָם הֱשִׁיבַנִי ה'. אָמְרָה נִשְׁמְתָא אֲנָא מְלֵאָה אֲזִלְנָא לְהַאי (נראה מהאי) עָלְמָא וּכְעָן רֵיקָן הֶחֱזִירַנִי ה' בְּהַאי גּוּפָא. ועכ\"ד אִי זָכָה בַּר נָשׁ לְאִתְעַסְּקָא בְּאוֹרַיְתָא הִיא חֶבְרוֹן שֶׁהִיא אוֹרַיְתָא דְּאִסְתַּלְּקַת מִנִּשְׁמְתָא אִתְחַבְּרַת לָהּ. דְּנִשְׁמְתָא אִיהִי מִכֻּרְסֵי יְקָרָא ו' אוֹרַיְתָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא תּוֹרַת ה' תְּמִימָה. עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. ואַף עַל גַּב דְּאִיהוּ בַּר נָשׁ בִּישָׁא כְּנַעֲנִי דְּאַסְחַר לֵהּ יֵצֶר רָע אִי מַתְקַף בְּהַהִיא חֶבְרוֹן אִתְחַבְּרַת לֵהּ. ד\"א הִיא חֶבְרוֹן דָּא שְׁכִינְתָּא\"אַף עַל גַּב דְּאִתְרְחָקַת מִנֵּהּ דְּקוּדְשָׁא בְּרִיךְ הוּא הִיא חֶבְרוֹן לְגַבֵּהּ. כְּגַוְנָא דְּיִשְׂרָאֵל דְּאָמְרִין הָא אֱלֹהֵינוּ בעלונו אֲדוֹנִים זוּלָתֶךָ. ועכ\"ד לְבַד בָּךְ נַזְכִּיר שִׁמְךָ אַף עַל גַּב דְּאִתְרְחַק הָדָא הוּא דִּכְתִיב בְּרַח דּוֹדִי. ועכ\"ד לִבָּא דִּידָן וּפוּמָא דִּידָן לָאו אִיהוּ אִתְפְּרַשׁ מִנָּךְ כְּדִכְתִיב וּדְמֵה לְךָ לִצְבִי (שם). כְּעָן אֲנָן מְיַחֲדִין שִׁמְךָ בְּכָל יוֹם וְאָמְרִין שְׁמַע יִשְׂרָאֵל בְּלִבָּא בְּפוּמָא וּבְמַחֲשָׁבָה. וּבְגִין דָּא הִיא חֶבְרוֹן בְּגִין דִּשְׁכִינְתָּא לֹא זָזָה מִקּוּדְשָׁא בְּרִיךְ הוּא, וְיִשְׂרָאֵל מְיַחֲדִין שְׁמֵהּ בְּכָל יוֹמָא וְסָבְלִין כַּמָּה מַכְתְּשִׁין עָלֵהּ כְּמָה דְּאוֹקְמוּהּ קַדְמָאִין:</p>"],[9514015403,"<p>פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר. וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה. אִלֵּין מֵאָה בִּרְכָּאן דְּאִשְׁתְּכָחוּ מֵחָכְמָה. וְעֶשְׂרִים שָׁנָה מִסִּטְרָא דְּכֶתֶר. וְשֶׁבַע שָׁנִים מִסִּטְרָא דְּאִימָּא עִלָּאָה. וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע דָּא קְרִיַת שְׁמַע. דְּלָא מִיתַת הַאי צַדֶּקֶת עַל יְדֵי נָחָשׁ, אֶלָּא נַפְקַת רוּחָא דִּילֵהּ בִּקְרִיאַת שְׁמַע בְּאַרְבַּע אַתְוָן הִיא חֶבְרוֹן, חִבּוּרָא דְּנִשְׁמְתָא הִילֵהּ הִיא שְׁכִינְתָּא דְּאִיהִי קִרְיַת אַרְבַּע, ד' אַתְוָן דִּשְׁמָא קַדִּישָׁא דְּאִנּוּן י' יְהוָֹה. ה' אֱלֹהֵינוּ. ו' יְהוָֹה. ה' אֶחָד. בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד עכ\"מ:</p>"],[9514015404,"<p>וַיַּרְא אֵלָיו ה' וַיֹּאמֶר אַל תֵּרֵד מִצְרַיְמָה וְכוּ'. (בראשית כ״ו:ב׳) פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר וַיֵּרָא אֵלָיו ה', מִסִּטְרָא דְּאַסְפַּקְלַרְיָא דְּנַהֲרָא הָכֵי אִיהוּ, ה' בְּכָל סְפִירָה וּסְפִירָה כְּנִשְׁמְתָא בְּגוּפָא דְּבַר נָשׁ. וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִתְּמַר וַיַּרְא אֵלָיו ה', אִתְגַּלֵּי בְּרַחֲמֵי לְיִשְׂרָאֵל כְּגַוְנָא דְּאִתְגְּלֵי לוֹן בְּפֻרְקָנָא דְּגָלוּתָא דְּמִצְרַיִם דְּאִתְּמַר בֵּהּ אֲנִי וְלֹא מַלְאָךְ אֲנִי וְלֹא שָׂרָף. אַדְּהָכֵי הָא סָבָא דְּסָבִין אִזְדְּמַן לְגַבֵּי וְאָמַר, בּוּצִינָא קַדִּישָׁא מִסִּטְרָא דִּנְבוּאָה כָּל סְפִירָן אִתְכְּלִילָן תַּמָּן. אֲבָל שֵׁם יְ\"יָ הוּא בְּכָל אֲתַר וַדַּאי. אֲבָל נְבוּאָה דַּרְגָּא יְדִיעָה אִית לָהּ. וְהָכֵי צְלוֹתָא כָּל סְפִירָן אִתְכְּלִילָן בָּהּ. אֲבָל כָּל חֲדָא וַחֲדָא אִית לָהּ דַּרְגָּא יְדִיעָה דַּרְגָּא יְדִיעָא אִית לָהּ וְהָכֵי בְּכָל אִנּוּן פִּקּוּדָא כָּל פִּקּוּדָא וּפִקּוּדָא כָּל סְפִירָן אִתְכְּלִילָן בָּהּ אֲבָל. וּשְׁכִינְתָּא אִיהִי מִצְוָה דְּכֻלְּהוּ פִּקּוּדִין וּבֵהּ אִתְכְּלִילָן כֻּלְּהוּ נְבִיאִים וַדַּאי נֶצַח וָהוֹד, וּבְהוֹן אִתְכַּלְּיָן עַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁכִינְתָּא. עַמּוּדָא דְּאֶמְצָעִיתָא מִתַּמָּן אִתְקְרֵי אַסְפַּקְלַרְיָא דְּנַהֲרָא דְּנֶצַח דְּבֵהּ אִיהוּ אוֹר צַח. וּבְגִינֵהּ אִתְּמַר וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. שְׁכִינְתָּא דְּאִיהִי מַלְכוּתָא קַדִּישָׁא מִסִּטְרָא דְּהוֹד אִתְקְרִיאַת אַסְפַּקְלַרְיָא דְּלָא נַהֲרָא. וְאִנּוּן כְּתוּבִים מִזֶּה וּמִזֶּה. וּכְתִיב בּוֹ מִשְּׁנֵי עֶבְרֵיהֶם וְאִנּוּן יְמִינָא וּשְׂמָאלָא חֶסֶד וּגְבוּרָה דִּי בְּהוֹן תְּרֵין יוּדִין (נראה ידין) לְמִכְתַּב. וְאִנּוּן ה' ה' חָמֵשׁ אֶצְבְּעָן דְּיַד יְמִינָא, וְחָמֵשׁ אֶצְבְּעָן דְּיָד שְׂמָאלָא. רוּחָא דְּקֻדְשָׁא ו' אִיהוּ תּוֹרָה שֶׁבִּכְתָב עָלַיְהוּ ה\"ה ו' וְעִם י' דְּהִיא חָכְמָה אִתְעֲבִידַת יהו'ה וְאִנּוּן נֶצַח וָהוֹד תְּרֵין נְבִיאֵי, תְּרֵין כְּתוּבִים, תְּרֵין לוּחִין דְּאוֹרַיְתָא דְּאִתְיְהִיבוּ מִימִינָא וּשְׂמָאלָא. עַמּוּדָא דְּאֶמְצָעִיתָא אִיהוּ אוֹרַיְתָא דְּבִכְתָב מִימִינָא. מַלְכוּת אוֹרַיְתָא דִּבְעַל פֶּה מִשְּׂמָאלָא, וְאִיהוּ אַסְפַּקְלַרְיָא דְּנַהֲרָא מִימִינָא וְאִיהִי אַסְפַּקְלַרְיָא דְּלָא נַהֲרָא מִשְּׂמָאלָא. וְאִנּוּן רוּחָא דְּקֻדְשָׁא דְּכָר וְנוּקְבָא. מִסִּטְרָא דְּצַדִּיק מִתְחַבְּרָן עַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁכִינְתָּא בֵּין בְּאוֹרַיְתָא בֵּין בַּכְּתוּבִים בֵּין בַּנְּבִיאִים. וּבְגִין דָּא כִּי כָּל בַּשָּׁמַיִם וּבָאָרֶץ.</p>"],[9514015405,"<p>וְהָא אוֹקְמוּהּ דְּאָחִיד בִּשְׁמַיָּא וּבְאַרְעָא דִּבְכָל דַּרְגִּין אִנּוּן יְמִינָא וּשְׂמָאלָא לֵית יחוְדָא וְקוּרְבָא לְקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא בְּצַדִּיק דְּאִנּוּן כְּאִילָנָא דְּעַנְפִין מִתְפָּרְדִין לִימִינָא וּשְׂמָאלָא, וּמִתְיַחֲדִין לְתַתָּא כְּשֹׁרֶשׁ דְּאִיהוּ אֲגֻדָּה. דְּאִיהוּ צַדִּיק עִקָּרָא דְּיִחוּדָא. וּכְגַוְנָא דְּצַדִּיק אִיהוּ עִקָּרָא דְּיִחוּדָא לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא לְתַתָּא, הָכֵי אִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא קוּרְבָא ויחוְדָא וְעִקָּרָא לְאַבָּא וְאִימָּא. וְהָכֵי כְּגַוְנָא דָּא תְּפִלָּה מְעוֹמֵד וּתְפִלָּה מְיוֹשֵׁב אִתְכְּלִילוּ בְּצַדִּיק חַי עָלְמִין כְּלִילָא חַ\"י בִּרְכָּאן דִּצְלוֹתָא, וּצְלוֹתָא דְּשַׁחֲרִית וּצְלוֹתָא דְּמִנְחָה אִנּוּן יְמִינָא וּשְׂמָאלָא. תַּמָּן אַבָּא וְאִימָּא וְאִתְכְּלִילָן בְּעַמּוּדָא דְּאֶמְצָעִיתָא דְּאִיהוּ צְלוֹתָא דְּעַרְבִית דְּבֵהּ (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם, דַּרְגָּא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִיהוּ עִקָּרָא דִּתְפִלִּין, וּבֵהּ צָרִיךְ לְקַשְּׁרָא (נ\"א לסדרא) לוֹן כְּגַוְנָא דָּא חָכְמָה קֹדֶשׁ לִי וְדָא י' בִּינָה. וְהָיָה כִּי יְבִיאֲךָ וְדָא ה' שְׁמַע יִשְׂרָאֵל לִימִינָא ו'. וְהָיָה אִם שָׁמוֹעַ לִשְׂמָאלָא וְדָא ה' וּבְעַמּוּדָא דְּאֶמְצָעִיתָא אִתְכְּלִילָן, וְכַד תְּפִלִּין דְּרֹאשׁ וּדְיָד אִתְכְּלִילָן בֵּהּ אִתְקְרִיאוּ תְּפִלִּין. וּבֵהּ אִנּוּן פקוְדָא חֲדָא וְלֹא צָרִיךְ לְאַפְסָקָא כְּמָא דְּאוֹקְמוּהּ סָח בֵּין תְּפִלָּה לִתְפִלָּה עֲבֵרָה הִיא בְּיָדוֹ. וְהַאי אִיהוּ עִקָּרָא דִּגְמָרָא. וְאִלֵּין דְּעָבְדִין לֵהּ תְּרֵי פִּקּוּדִין דִּירוּשַׁלְמִי, אִיהוּ מִימִינָא וּשְׂמָאלָא דְּתַמָּן עַנְפִּין מִתְפָּרְדִין דְּמִסִּטְרָא דִּימִינָא וּשְׂמָאלָא. שְׁתַּיִם דְּבַר אֱלֹהִים צָרִיךְ לְבָרְכָא עָלַיְהוּ תְּרֵין בִּרְכָּאן חַד לְהָנִיחַ תְּפִלִּין עַל שֶׁל יָד, וְחַד עַל מִצְוֹת תְּפִלִּין שֶׁל רֹאשׁ. וְאִם סָח בֵּנְתַיִם מְבָרֵךְ עַל שֶׁל רֹאשׁ שְׁתַּיִם. אֲבָל מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא עָלַיְהוּ אִתְּמַר אַחַת דְּבַר אֱלֹהִים. וְלֹא צָרִיךְ אֶלָּא בִּרְכָתָא חֲדָא. כִּי אֶחָד קְרָאתִיו. וְאִם סָח בֵּין תְּפִלָּה שֶׁל יָד לִתְפִלָּה שֶׁל רֹאשׁ בְּעַמּוּדָא דְּאֶמְצָעִיתָא אִיהוּ עָבִיד פֵּרוּד בְּיִחוּדָא. וּבְגִין דָּא עֲבֵרָה הִיא בְּיָדוֹ וְלֹא מִצְוָה.</p>"],[9514015406,"<p>וְלֵית עֲבֵרָה אֶלָּא מָוֶת דְּאִתְּמַר רַגְלֵהּ יוֹרְדוֹת מָוֶת דְּעָלַהּ אִתְּמַר כִּי הַמָּוֶת יַפְרִיד בֵּין א'ח לְד'. וּבְגִין דָּא עֲבֵרָה הִיא בְּיָדוֹ וְחוֹזְרִין עָלֶיהָ מֵעוֹרְכֵי הַמִּלְחָמָה. וּדְאִי נָפִיק מִתַּמָּן בְּחוֹבָא דָּא יָמוּת. וְהַאי אִיהוּ אַחַת דְּבַר אֱלֹהִים. זֶה צַדִּיק דְּאִיהוּ יוֹם שַׁבָּת. זָכוֹר וְשָׁמוֹר בְּדִבּוּר אֶחָד צְרִיכִין לְיַחֲדָא לוֹן בֵּהּ וּלְמֶעֱבַד לוֹן חַד. וְהָא אוֹקְמוּהּ זָכוֹר לִזְכֹּר שָׁמוֹר לְנוּקְבָא. אֲבָל מִסִּטְרָא דִּימִינָא וּשְׂמָאלָא אִנּוּן תַּרְוַיְהוּ תְּרֵין פִּקּוּדִין. וּכְגַוְנָא דָּא כָּל פִּקּוּדִין. וּבְגִין דָּא מַחֲלֹקֶת דְּאִיהוּ בֵּין חַבְרַיָּא בִּתְפִלִּין וּשְׁאָר פִּקּוּדִין בִּימִינָא וּשְׂמָאלָא אִיהוּ. אֲבָל בְּעַמּוּדָא דְּאֶמְצָעִיתָא לֵית תַּמָּן מַחֲלֹקֶת. בְּגִין דְּאִיהוּ עִקָּרָא דִּגְמָרָא דְּאִיהִי שְׁלֵמָה. ומִתַּמָּן אִתְקְרֵי יַעֲקֹב אִישׁ תָּם אִיהוּ ו' כָּלִיל שִׁית סִדְרֵי מִשְׁנָה. ה' גְּמָרָא דִילָהּ אִיהִי תָּם בִּתְלָת אֲבָהָן יְה\"וּ וּבֵהּ אִשְׁתְּלִים יְהוָֹה. וּבְגִין דָּא בְּכָל אֲתַר דְּעַנְפִין מִתְפָּרְדִין לִימִינָא וּשְׂמָאלָא. אֲבָל לְתַתָּא אִקְּרֵי אֲגֻדָּה חֲדָא בְּעַמּוּדָא דְּאֶמְצָעִיתָא. וּבְגִין דָּא וַיַּרְא אֵלָיו ה' וַיֹּאמֶר אַל תֵּרֵד מִצְרַיְמָה. דָּא דַּרְגָּא בִּישָׁא דִּגְרָמַת כַּפְנָא דְּאוֹרַיְתָא וַעֲנִיּוּתָא דְּפִקּוּדִין דְּאוֹרַיְתָא, דְּהָא אוֹקְמוּהּ שָׁכֵן בָּאָרֶץ דָּא שְׁכִינְתָּא וְהָא אוֹקְמוּהּ קַדְמָאִין, כָּל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. וְאַבְרָם דַּרְגֵּהּ אַרְיֵה דְּאִתְּמַר בֵּהּ גּוּר אַרְיֵה. וּבְגִין דָּא אָמַר לוֹ הַקּוּדְשָׁא בְּרִיךְ הוּא גּוּר בָּאָרֶץ הַזֹּאת. יְמִינָא תַּמָּן יְה\"וּ דְּסָלִיק לְחֻשְׁבַּן אֶהְיֶ\"ה וְתַמָּן ו' בְּגִין ה' דְּאַבְרָהָם דְּאִיהִי הָאָרֶץ. וּמִסִּטְרָא דִּימִינָא אִתְקְרֵי בָּאָרֶץ דְּתַמָּן אָב ב'א בְּהִפּוּךְ אַתְוָן אָב וְהַאי אִיהוּ בָּאָרֶ\"ץ כִּי אָב הֲמוֹן גּוֹיִם נְתַתִּיךָ. וְאֶהְיֶה עִמָּךְ דָּא יה'ו בְּחֻשְׁבַּן אֶהְיֶה. בְּגִין ה' וְאֶהְיֶה עִמָּךְ ו' דְּאִיהוּ בֵּן יָ\"הּ מִן אֶהְיֶה עִמָּךְ. וַאֲבָרֶכְךָ דְּבִרְכָאָן מִסִּטְרָא דְּכַהֲנָא אִנּוּן. שְׁכִינְתָּא עִלָּאָה אִתְקְרִיאַת בְּרָכָה מִסִּטְרָא דִּימִינָא. וְקִדּוּשָׁא מִסִּטְרָא דִּשְׂמָאלָא. וְעַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרֵי יְבָרֵךְ הָדָא הוּא דִּכְתִיב בָּךְ יְבָרֵךְ יִשְׂרָאֵל. וּמִסִּטְרָא דִּשְׂמָאלָא אִתְקְרֵי קֹדֶשׁ הָדָא הוּא דִּכְתִיב קֹדֶשׁ יִשְׂרָאֵל לַה'.</p>"],[9514015407,"<p>וּמִקְדָּשִׁי תִירָאוּ וְקָדוֹשׁ מִסִּטְרָא דִּשְׂמָאלָא. וּבְגִין דְּאִיהִי בְּרָכָה מִסִּטְרָא דִּימִינָא אָמַר וַאֲבָרֶכְךָ כִּי לְךָ וּלְזַרְעֲךָ. זֶרַע מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִיהוּ לְעֵלָּא, וּמִסִּטְרָא דְּצַדִּיק לְתַתָּא, וְהַאי אִיהוּ עַל כָּל זֶרַע זָרוּעַ. זָרוּעַ לְעֵלָּא. זֶרַע לְתַתָּא. דְּמָאן דְּנָטִיר בְּרִית סָלִיק עַל כָּל אִלֵּין קְלִפִּין דְּאִנּוּן עָרְלָה וּפְרִיעָה, דְּתַמָּן סַמָּאֵל וְנָחָשׁ מְמָנָן דְּכָל אֻמִּין דְּעָלְמָא. פ\"כ וּבְגִין דָּא כִּי לְךָ וּלְזַרְעֲךָ אֶתֵּן אֶת כָּל הָאֲרָצוֹת הָאֵל. דְּאִנּוּן שֻׁלְטָנוּתָא דְּאֵל אֶחָד. וַהֲקִמֹתִי אֶת הַשְּׁבוּעָה. שְׁבוּעָה אִיהִי שְׁכִינְתָּא קִיּוּמָא דִּילָהּ עַמּוּדָא דְּאֶמְצָעִיתָא. אֲשֶׁר נִשְׁבַּעְתִּי לְאַבְרָהָם אָבִיךָ. דְּבֵהּ פֻּרְקָנָא הָדָא הוּא דִּכְתִיב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקוֹלִי. עָקֵב רֹאשִׁי תֵּבוֹת ע' עֲנָוָה. ק' קְדֻשָּׁה. ב' בְּרָכָה. סַנְדָּל לַעֲנָוָה יִרְאָה. וּבְגִין דָּא עָקֵב עֲנָוָה יִרְאַת ה'. עֲנָוָה מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וּבְגִין דְּמֹשֶׁה הֲוָה מִתַּמָּן, אִתְּמַר בֵּהּ וְהָאִישׁ מֹשֶׁה עָנָיו מְאֹד. וַעֲנָוָה מִימִינָא וּשְׁכִינְתָּא יִרְאָה מִסִּטְרָא דִּשְׂמָאלָא. וּבְגִין דִּשְׁכִינְתָּא אִיהִי עָקֵב לְעַמּוּדָא דְּאֶמְצָעִיתָא אִתְּמַר בֵּהּ, רֹאשׁ דְּבָרְךָ אֱמֶת. דְּאִיהוּ בִּשְׁכִינְתָּא עָקֵב עֲנָוָה יִרְאַת ה'. כְּהַאי אִיהוּ. הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. וּלְבָתַר אִתְּמַר בְּיַעֲקֹב הוּא יְשׁוּפְךָ רֹאשׁ הָדָא הוּא דִּכְתִיב וּפָקַדְתִּי עַל צְבָא הַמָּרוֹם בַּמָּרוֹם. וְיִשְׁמֹר מִשְׁמַרְתִּי דָּא שְׁכִינְתָּא דְּאִיהִי מִשְׁמֶרֶת תְּרוּמָתִי מִצְוֹתַי מִסִּטְרָא דִּימִינָא כְּלִילָן בִּרְמַ\"ח אֵבָרִים. חֻקּוֹתַי מִסִּטְרָא דִּשְׂמָאלָא דְּמִתַּמָּן כִּי חֹק לְיִשְׂרָאֵל הוּא. חֻקִּים וּמִשְׁפָּטִים אִנּוּן מִתַּמָּן גְּזֵרַת מַלְכָּא, דְּתַמָּן גְּזִירוּ דְּכָל דִּינִין. וְתוֹרֹתַי מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִיהוּ סֵפֶר תּוֹרָה. צַדִּיק אִיהוּ סֵפֶר תּוֹרָה עַמּוּדָא דְּאֶמְצָעִיתָא. וְאִיתֵּימָא צַדִּיקִים עוֹמְדִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם, אִלֵּין תָּגִין דְּסֵפֶר תּוֹרָה דְּאִנּוּן בֶּדֶ'ק חַיָּ'ה שעטנ'ז ג'ץ. וְאָמְרֵי מָארֵי מַתְנִיתִין אִלֵּין תָּגִין אִנּוּן זַיְינִין כְּאָדָם שֶׁאוֹחֵז כְּלֵי זַיִן בִּידֵהּ וּמֵנִיעַ לֵהּ לִימִינָא וְלִשְׂמָאלָא וְלִקְדֻשָּׁה. וְזַיְינִין אִנּוּן בִּתְלָת עָשָׂר אַתְוָן ז'ן בדח'ק אִיהִי כְּמִין חֲטֹטֶרֶת דְּאָת זַיִן. וְאִתְעֲבִיד זֶה וְסִימָנִיךְ זֶ'ה ו'ד ז'חח'י. ז' צַדִּיק ח\"ק בְּכָל אוֹת וְאוֹת. וְאִיהוּ עִם י' עֲטָרָה עַל רֵישֵׁהּ:</p>"],[9514015408,"<p>וַיֵּשֶׁב יִצְחָק בִּגְרָר. תָּא חֲזֵי צָרִיךְ דְּלֹא יְהֵא דָּבֵק אוֹת בְּאוֹת, וְלֹא יְהֵא חָסֵר אוֹת מִן הַתֵּבָה וְלֹא מְשַׁנִּין מִפְּתוּחוֹת לִסְתוּמוֹת וּמִסְּתוּמוֹת לִפְתוּחוֹת. וְאִי לָאו סֵפֶר תּוֹרָה פָּסוּל. וְכָל תִּקּוּנָא לָמָּה, אֶלָּא אַתְוָן פְּתִיחָן מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה. סְתִימָן מִסִּטְרָא דְּאִמָּא עִלָּאָה עָלְמָא סְתִימָא. וְאִנּוּן מֵ'ם דָּא פְּתִיחָא וְדָא סְתִימָא. מ' פְּתוּחָה מַלְכוּת. ם סְתִימָא בִּינָה מִסִּטְרָא דִּימִינָא וּשְׂמָאלָא, דְּעַנְפִין מִתְפָּרְדִין לֹא יִדָּבֵק אוֹת בְּאוֹת, וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא דְּאִיהוּ שֶׁקֶל הַקֹּדֶשׁ, לֹא יוֹסִיף אוֹת וְלֹא יְחַסֵּר אוֹת. דְּכָל הַמּוֹסִיף גּוֹרֵעַ. וְאִם הִדְבִּיק נִגְרָר. וּבְגִין דָּא וַיֵּשֶׁב יִצְחָק בִּגְרָר וְגוֹ'. אַדְּהָכִי הָא יַנּוּקָא אִזְדְּמַן בֵּינַיְהוּ וְאָמַר, אַמַּאי לֵית נִקּוּד בְּסֵפֶר תּוֹרָה. אָמַר לֵהּ בְּרִי, כָּל נְקֻדָּה אִיהִי תְּנוּעָה דְּאַתְוָן. כְּגוֹן פִּרְקִין דְּאִנּוּן תְּנוּעִין דְּאֵבָרִין דְּגוּפָא. וְכָל תְּנוּעָה אִנּוּן מִסִּטְרָא דְּחָכְמָה. וּבְגִין לְאִשְׁתְּמוֹדַע דְּסֵפֶר תּוֹרָה, אִיהוּ מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, לֵית בֵּהּ נִקּוּדִין. וְכָל נִקּוּדִין אִנּוּן בַּגּוּף עֵינִין אַנְפִּין אוּדְנִין. חוֹטָמָא דְּכֻלְּהוּ עַל פֶּה. וּבְגִין דְּאוֹרַיְתָא דְּבִכְתָב אִתְיְהִיבַת מִסִּטְרָא דִּימִינָא, דְּתַמָּן כְּתִיבָה, אוֹקְמוּהּ דְּאוֹרַיְתָא דְּכָתַב סֵפֶר תּוֹרָה דְּלָא לְמִקְרֵי לֵהּ עַל פֶּה, וְאִתְּמַר דְּלֵית לֵהּ נִקּוּדִין לְאוֹרַיְתָא דִּבְעַל פֶּה אִית טַעֲמֵי:</p>"],[9514015409,"<p>דָּבָר אַחֵר וַיֵּרָא אֵלָיו ה'. תָּא חֲזֵי אִית נְבוּאָה מֵרְאִיָּה, וְאִית נְבוּאָה מֵרֵיחָא, וְאִית נְבוּאָה מִשְּׁמִיעָה, וְאִית נְבוּאָה מִדִּבּוּר. וְאִנּוּן ד' מֶרְכָּבוֹת לְשֵׁם יְהוָֹה. בִּרְאִיָּה, בְּרִיאָה דְּאִיהִי מַרְאֶה, וְלָקֳבֵל מֶרְכָּבָה דִּלְעֵלָּא מָנֵי קוּדְשָׁא בְּרִיךְ הוּא נַעֲשֶׂה אָדָם. וְהָא אַקְשׁוּ קַדְמָאִין, בָּתַר דְּכֻלְּהוּ בִּרְיָן דְּבָרָא בְּעוֹבָדָא דִּבְרֵאשִׁית, אַדְכִּיר בְּרִיאָה בְּלִישְׁנָא דְּיָחִיד. אַמַּאי אַדְכִּיר בְּנַעֲשֶׂה אָדָם בְּלִישְׁנָא דְּרַבִּים, לְמֵיהַב פִּתְחוֹן פֶּה לַמִּינִים וְלַמּוּמָרִים. אֶלָּא הָכָא כְּתִיב (הושע י״ד:י׳) וּבַאֲבֹד רְשָׁעִים רִנָּה. כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ' וּפֹשְׁעִים יִכָּשְׁלוּ בָּם. לְקַיְּמָא בְּהוּ וּבַאֲבֹד רְשָׁעִים רִנָּה. דְּהָא אוֹרַיְתָא קָא סָתִים דְּאִיהוּ בָּרָא לָאָדָם עִלָּאָה קַדְמָאָה, הָדָא הוּא דִּכְתִיב וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. אֶת לְרַבּוֹת דְּבָרָא לֵהּ בְּדִיּוֹקְנָא דְּאָדָם עִלָּאָה בְּמֶרְכַּבְתָּא, דְּאִתְּמַר בֵּהּ וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּבָרָא לֵהּ בִּתְרֵין דִּיּוֹקְנִין בְּצֶלֶם דְּאִנּוּן אָדָם דְּכִסֵּא הַכָּבוֹד מָרוֹם. וְאָדָם דְּכִסֵּא תִּנְיָנָא דְּאִתְּמַר בֵּהּ מֵרִאשׁוֹן. וְזֶהוּ מָרוֹם מֵרִאשׁוֹן. וּמַה דְּאָמַר נַעֲשֶׂה אָדָם, הַאי לְלַמֵּד לְכָל חַד וְחַד מִיִּשְׂרָאֵל דְּאִנּוּן דְּכָר וְנוּקְבָא לְשַׁתְּפָא לֵהּ בְּזִוּוּגֵהּ. דְּאִם ה' לֹא יִבְנֶה בַּיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. וּבְגִין דָּא אָמַר קָרָא בְּכָל דְּרָכֶיךָ דָעֵהוּ וְהוּא יְיַשֵּׁר אָרְחוֹתֶיךָ. דְּאִתְּמַר בְּהוֹן כִּי יְשָׁרִים דַּרְכֵי ה'. דְּוַדַּאי אִתְּמַר בְּעִלַּת הָעִלּוֹת תְּרֵין עָלְמִין דְּצִיֵּר בְּהוֹן עִלַּת עַל כֹּלָּא. וְאִנּוּן י' מֵאִישׁ, ה' מֵאִשָּׁה. תְּרֵין עָלְמִין דְּצִיֵּר בְּהוֹן עִלַּת עַל כֹּלָּא, אִנּוּן ו' ה' עָלְמָא דֵּין וְעָלְמָא דְּאָתֵי. וְדָא יָ'הּ. וְדָא אִיהוּ יוּ\"ד הֵ\"א וָא\"ו הֵ\"א. וְאָמַר עִלַּת עַל כֹּלָּא אַף עַל גַּב דִּבְאִלֵּין אִתְּמַר בְּאִלֵּין אַתְוָן אִתְבְּרֵי עָלְמָא. וְכֻרְסֵא, לָאָדָם לָשֶׁבֶת בַּיִת לָשֶׁבֶת עַל הַכִּסֵּא, דִּבְהוֹן אי\"ה או\"ה, וּבְהוֹן אִתְקְרִיאוּ יִשְׂרָאֵל בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. וְאִתְּמַר בְּהוֹן אָדָם אַתֶּם. שִׁתְּפוּנִי בַּהֲדַיְכוּ בְּאִלֵּין אַתְוָן וְיִתְקַיִּם עוֹבָדֵיכוֹן. דַּאֲנָא הוּא דְּבָרָאתִי כָּל עָלְמִין, וְכָל כָּרְסְיָן וְחֵיוָן וּמַלְאָכִין, וְכָל צָבָא עִלָּאִין וּבְנֵי אָדָם בְּאִלֵּין אַתְוָן. וְאַף עַל גַּב דְּאִית בְּיִשְׂרָאֵל אִלֵּין אַתְוָן בְּגִין אוֹרַיְתָא דְּיָהַב לוֹן. לֹא יִשְׁתַּכְּחוּן בְּאִלֵּין אַתְוָן לְמֶעֱבַד עוֹבָדָא בְּהוֹן דְּלָא יִשְׁתַּתְּפוּן לִי בַּהֲדַיְהוּ. וּבְגִין דָּא אָמַר לוֹן נַעֲשֶׂה אָדָם בְּשִׁתּוּפָא דִּילִי וְלָאו אוֹרַיְתָא וּפִקּוּדָא עָבִיד פְּעֻלָּה וְעוֹבָדָא עֵלָּא וְתַתָּא פָּחוֹת מִנִּי. וּבְגִין דָּא בְּכָל דְּרָכֶיךָ דָּעֵהוּ. וְכָל אֻמִּין דְּעָלְמָא דְּלָא קַבִּילוּ מִנֵּהּ אוֹרַיְתָא, לֵית לוֹן יְדִיעָה בֵּהּ, וְאָזְלִין כְּעָאנָא בְּלֹא רָעֲיָא, וְאִתְּמַר בְּהוֹן כִּי כָּל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו, וְעָבְדִין אֱלֹהוּת סַגִּיאִין.</p>"],[9514015410,"<p>וְכָל יִשְׂרָאֵל דְּקַבִּילוּ מִנֵּהּ אוֹרַיְתָא, אִנּוּן עָבְדִין לֵהּ אֶחָד בֵּהּ, וּבְכָל אַתְוָן וּשְׁמָהָן קַדִּישִׁין דִּילֵהּ וּבְכָל מַשִּׁרְיָן עִלָּאִין וְתַתָּאִין דְּאִתְבְּרִיאוּ בְּהוּ. וּבְכָל בִּרְיָן עִלָּאִין וְתַתָּאִין וּלְעֵלָּא מִכֻּלְּהוּ אֶחָד וּלְתַתָּא מִכֻּלְּהוּ וּמִלְּגָאו דְּכֻלְּהוּ וּמַלְכָּא דְּכֻלְּהוּ אִיהוּ אֶחָד. מִבַּיִת וּמִחוּץ תִּצְפֶּנּוֹ. וְהָכֵי תּוֹכוֹ כְּבָרוֹ, הָכֵי אִיהוּ מִלְּגָאו דְּכָל עָלְמִין כְּמוֹ מִלְּבַר דְּכָל עָלְמִין לָא אִשְׁתַּנֵּי. וְלֵית שֵׁם וְחִבּוּר אַתְוָן דְּשֵׁם ה' וּבְכָל כִּנּוּיִין דִילֵהּ בַּר מִנֵּהּ. דְּאִי לָאו דְּאִיהוּ חִבֵּר בְּקִרְבֵּהּ בה' ו' בה', לֹא אִתְקְרִיאוּ אַתְוָן בְּשֵׁם יְהוָֹה, וְאִיהוּ מְחַבֵּר יְהוָֹ\"ה אֲדֹנָ\"י, וְאִיהוּ מְחַבֵּר יְהוָֹ\"ה בֵּאלֹהִים, דְּסָלִיק לְחֻשְׁבַּן אֶהְיֶ\"ה אֲדֹנָ\"י. וְאִיהוּ לָא אִתְקְרֵי פָּחוֹת מִנַּיְהוּ דְּאִיהוּ אֶחָד דִּמְחַבֵּר שְׁנַיִם, דְּאִנּוּן דְּכָר וְנוּקְבָא. וְעָבִיד לוֹן חַד. הָדָא הוּא דִּכְתִיב בְּאָדָם וְחַוָּה כִּי אֶחָד קְרָאתִיו. וְאִיהוּ מְשֻׁתָּף בְּבִנְיַן בֵּן וּבַת דְּאִנּוּן בָּנִים לִישְׁנָא דְּבִנְיָן. וְדָא אִיהוּ אִם יְיָ' לֹא יִבְנֶה בַּיִת. וְכָל עִנְיָנָא וְעוֹבָדָא דְּלָאו אִיהוּ מְשֻׁתָּף בֵּהּ, מַה כְּתִיב בָּהּ, כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְהָאָרֶץ כַּבֶּגֶד תִּכְלֶה. וּמִיָּד יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ דְּאִנּוּן בִּנְיָנָא וְשֻׁתָּפָא דִּילֵהּ. דְּכָל הֲבָלִים דְּאֻמִּין דְּעָלְמָא, אִנּוּן שָׁמַיִם וָאָרֶץ וַעֲתִידִין לְאוֹבָדָא. וְכָל הֲבָלִים דְּיִשְׂרָאֵל בְּיי' בְּיִחוּדֵהּ. אִנּוּן שָׁמַיִם וָאָרֶץ בִּנְיָנָא דִּילֵהּ, וּמַה הוּא חַי וְקַיָּם, הָכֵי עוֹבָדָא דִּילֵהּ חַי וְקַיָּם. וּבְגִין דָּא אָמַר חַי אֲנִי נְאֻם ה' אִם אֶחְפֹּץ בְּמוֹת הָרָשָׁע כִּי אִם בְּשׁוּבוֹ מִדַּרְכּוֹ וְחָיָה. וּכְגַוְנָא דְּאָמַר לְיִשְׂרָאֵל נַעֲשֶׂה אָדָם, הָכֵי אָמַר לִסְפִירָן נַעֲשֶׂה אָדָם, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא דְּאִיהוּ רִאשׁוֹן לְמַחֲשָׁבָה וְאַחֲרוֹן לְמַעֲשֶׂה, דְּאִנּוּן חָכְמָה בָּרֹאשׁ וְחָכְמָה בַּסּוֹף. דְּכָל סְפִירָה יָהִיב בֵּהּ חוּלָקֵהּ. וּבְגִין דָּא אִיהוּ בְּדִיּוֹקְנֵהּ מְאַסֵּף לְכָל הַמַּחֲנוֹת לַצְּבָאוֹת. וְרָעֲיָא מְהֵימָנָא בְּדִּיּוֹקְנֵהּ. וְאָמַר לַמַּלְאָכִין נַעֲשֶׂה אָדָם, וְדָא מְטַטְרוֹן, דְּכָל מַלְאָךְ וְחַיָּה שַׁוֵּי בֵּהּ חוּלָקִי'. וְהָכֵי אָמַר לִצְבָא הַשָּׁמַיִם לְמֶעֱבַד לְשִׁמְשָׁא בְּדִיּוֹקְנֵהּ, וְכָל כּוֹכָבָא יָהִיב בֵּהּ חוּלָקֵהּ, וְעִלַּת עַל כֹּלָּא אִשְׁתְּתַף בֵּהּ בְּכָל אֲתַר בְּתִפְאֶרֶ\"ת בִּמְטַטְרוֹ\"ן וּבְשִׁמְשָׁא, וְלֵית לְאַרְכָּא בְּהַאי.</p>"],[9514015411,"<p>וְעוֹד נַעֲשֶׂה אָדָם. לְאֻמָּן דְּזָרַע כַּמָּה זִרְעוֹנִין בְּבַת אַחַת, וְכָל אֶחָד נָפִיק לְיוֹמוֹי. לְבָתַר אָמַר לְאִלֵּין דְּאִנּוּן פּוֹעֲלִים, אֲנָא בָּעֵי דְּתִשְׁתַּתְּפוּ כֻּלְּכוּ לְמֶעֱבַד מָאנָא, וְכָל חַד מִנַּיְהוּ יָהִיב בֵּהּ חוּלָקֵהּ מִמַּה דִּיהָבִית בְּכוּ, וַאֲנָא אִשְׁתְּתַף עִמַּיְכוּ בְּהַהוּא מָאנָא חוּלָקָא מִנִּי. אָמְרוּ לֵהּ מַאי הַאי מָאנָא כָּל כָּךְ חָשִׁיב קָדָמָךְ דִּיהֵא כָּלִיל מִכֹּלָּא. אָמַר לוֹן הַאי מָאנָא אִיהוּ אָדָם דִּיהֵא בְּדִיּוֹקְנָא דְּאָדָם עִלָּאָה. אָמְרוּ לֵהּ אַמַּאי תֵּימָא לָן דְּכָל חַד וְחַד יָהִיב בֵּהּ חוּלָקֵהּ. וְהָא אַנְתְּ הוּא אָדוֹן דְּכֹלָּא, וְאַנְתְּ בָּרָאת כֹּלָּא, טֹל אַנְתְּ מִכָּל חַד וְחַד מַה דְּאַנְתְּ בָּעֵי, דְּלָא יְהֵא פִּתְחוֹן פֶּה לְאִנּוּן דְּלָא אִשְׁתְּמוֹדְעִין בָּךְ. דְּיֵמְרוּן דְּעוֹבָדָא דְּאָדָם אַנְתְּ צָרִיךְ מִשְּׁלִיחִין דִּילָךְ. אָמַר לוֹן לְמַלְכָּא דְּיָהַב מַתָּנָא לְעַבְדוֹי, וְיָהִיב לְכָל אֶחָד וְאֶחָד חוּלָקֵהּ וְאַחֲסַנְתֵּהּ מֵהַהוּא מַתָּנָא. לְבָתַר אָתָא עַבְדָּא מְהֵימָנָא לְגַבֵּהּ וְשָׁאִיל לֵהּ מַתָּנָה. אָמַר מַלְכָּא הַאי עַבְדָּא פְּלַח לִי בְּכָל אֵבָרִין דִּילֵהּ. הָכֵי אֲנָא בָּעֵי לְמֶעֱבַד מָאנָא דִּילֵהּ מַתָּנָה בְּכָל חֵילִין דִּילִי מֶה עָבַד כְּנַשׁ כָּל מַשִּׁרְיָן דִּילֵהּ וְאָמַר בָּעֵינָא מִנַּיְכוּ דַּל חַד וְחַד יָהִיב מַתָּנָה. מִדִּידֵהּ לְהַאי עַבְדָּא, וַאֲנָה אִשְׁתְּתַף עִמְּכוֹן וְאַתֶּם בֵּהּ מַתָּנָה מִדִּילִי. מִנְּהוֹן אַקְשׁוּ וְאָמְרוּ מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ. וּמִנְּהוֹן אָמְרֵי בְּרַעֲוָא שְׁלִים. אוּף הָכֵי קֹדֶם דְּאִתְבְּרֵי עָלְמָא, עָאלוּ יִשְׂרָאֵל בְּמַחֲשָׁבָה לְהִבָּרְאוֹת, קֹדֶם דְּאִתְבְּרִיאוּ מַלְאֲכִין וְכָל בִּרְיָן דְּעָלְמָא דְּעוֹבָדָא דִּבְרֵאשִׁית. ובחביהו דִּילְהוֹן, אַנָּח לְעוֹבָדָא דִּילְהוֹן דִּיהוֹן בַּתְרָאִין לְעוֹבָדָא דִּבְרֵאשִׁית. וְאָמַר עָלֵהּ נַעֲשֶׂה אָדָם. וְאַמַּאי אֶלָּא בְּגִין חֲבִיבוּ דַּאֲבוּהוֹן דְּבִשְׁמַיָּא דְּאִתְקְרֵי יִשְׂרָאֵל. וְאִנּוּן הֲווֹ עֲתִידִין לְאִתְקְרֵי בִּשְׁמֵהּ יִשְׂרָאֵל, כָּנִישׁ לְעִלָּאִין וְתַתָּאִין לְמֵיהַב חוּלָק' מִכֻּלְּהוּ. בְּדֵין דְּאִי חָב אָדָם, כֻּלְּהוּ אִשְׁתְּכָחוּ חֲסֵרִין בְּהוֹן, מֵהַהוּא חוּלָקָא דִּיהָבוּ בֵּהּ, וְכֻלְּהוּ בָּעָאָן רַחֲמֵי בְּגִינֵהּ. וְאִיהוּ יְהַב בְּהוֹן מִדִּילֵהּ, בְּגִין דִּמְרָוָן לֵהּ עֲשֵׂה לְמַעַנְךָ אִם לֹא לְמַעֲנֵנוּ, בְּגִין הַהוּא חוּלָקָא דִּילָךְ דְּיָהֲבַת בְּיִשְׂרָאֵל. הָדָא הוּא דִּכְתִיב כִּי חֵלֶק יְיָ' עַמּוֹ. וְאִיהוּ מָחִיל לוֹן בְּגִין הַהוּא חוּלָקָא דִּילֵהּ דִּשְׁמֵהּ דְּיָהַב בְּהוֹן. דְּאִם לֹא יְהִיבוּ אִנּוּן מִגַּרְמַיְהוּ חולק' בֵּהּ בִּרְעוּתַיְהוּ, כֻּלְּהוּ הֲווֹ טַעֲנִין עָלֵהּ, דְּאַנְתְּ נְטִילַת מִנָּן עַל כרחנ', חולק' דְּאִיהוּ בָּאָדָם מִכָּל חַד וְחַד, וְלֹא הֲווֹ מְרַחֲמֵי עלינ. וּבְגִין דְּלָא יְהֵא לוֹן פִּתְחוֹן פֶּה. בְּגִין דָּא לֹא בָּעָא לנטל' חולק' אֶלָּא בִּרְעוּתָא דִּילְהוֹן. כְּגַוְנָא דָּא דְּאִתְּמַר בְּרָעֲיָא מְהֵימָנָא, עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶׁבִי לָקַחְתָּ מַתָּנוֹת בָּאָדָם. וּבְגִין דְּמַזִּיקִין סָרְחוּ לְגַבֵּהּ, וְלֹא בָּעוּ לְמֵיהַב בֵּהּ חוּלָקָא, וְאָמְרוּ מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וְגוֹ', לֹא בָּרָא לוֹן לְבוּשִׁין דְּאִנּוּן גּוּפִין דִּלְהוֹן. וְאִנּוּן שַׂנְאִין לוֹן. וְעַל כֵּן מְמָנָן דְּעַל עָ\"ב אֻמִּין, דְּאִנּוּן קַמָּךְ, כְּגַוְנָא כַּד יִשְׂרָאֵל מְחֻיָּבִין לַאֲבוּהוֹן דְּבִשְׁמַיָּא, אִנּוּן אֻמִּין דְּעָלְמָא רְצוּעִין בִּידָא דְּבוֹרֵא עָלְמָא לְאַלְקָאָה לוֹן בְּהוּ.</p>"],[9514015412,"<p>וְכַד חַזְרִין בִּתְיוּבְתָּא זָרִיק רְצוּעִין מִידֵהּ, וְלָא יְהֵא בְּהוֹן מַמָּשׁ. דְּחֵילָא דִּרְצוּעִין לָאו אִיהוּ אֶלָּא בִּידָא דמיי' (נראה דמאן) דְּנָטִיל. דְּעָלַיְהוּ אִתְּמַר כָּל הַגּוֹיִים כְּאַיִן נֶגְדּוֹ. וּבְגִין דְּיִשְׂרָאֵל אִית בְּהוּ חוּלָק' מִבּוֹרֵא עָלְמִין דְּאִיהוּ עִלַּת עַל כֹּלָּא. וּמֵעֶשֶׂר סְפִירָאָן וּמִכָּרְסְיָן וּמַלְאָכִין וְכוֹכָבַיָּא וּמַזָּלִין כַּד חַזְרִין בִּתְשׁוּבָה הַכֹּל מַה דְּאִתְנְטִילוּ בעון רַחֲמֵי עָלַיְהוּ. בַּר מִשֵּׁדִין וּמַזִּיקִין וְחֵילִין דִּמְסָאֲבוּ, דְּאִתְּמַר בְּיִשְׂרָאֵל אַל תִטַמְאוּ בְּכָל אֵלֶּה, דְּלֵית לוֹן חוּלָקָא בְּהוֹן. וּבְגִין דָּא אֻמִּין דְּעָלְמָא דְּנִשְׁמָתִין דִּילְהוֹן מֵאִנּוּן חֵילִין דִּמְסָאֲבוּ, לֵית לְשַׁתְּפָא בְּהוֹן לַאֲכִילָה וּשְׁתִיָּה, וְלֹא בְּכָל עוֹבָדֵיהוֹן, דְּעָלַיְהוּ כְּתִיב אֲשֶׁר חֵלֶק ה' אֱלֹהֶיךָ וְגוֹ', וּבְךָ בָּחַר ה'. וְעָלַיְהוּ אִתְּמַר כִּי כָּל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו וְגוֹ', דְּאִיהוּ יָחִיד וּמְיֻחָד בְּכָל מַשִּׁרְיָן דִּכְלִילָן בְּהוֹן. וּבְגִין דְּיִשְׂרָאֵל כְּלִילָן מֵעִלָּאִין וְתַתָּאִין, וְעִלַּת עַל כֹּלָּא שַׁוֵּי שְׁמֵהּ בְּהוֹן, וְאִנּוּן רְחִימִין יַתִּיר מִמַּלְאֲכֵי הַשָּׁרֵת, בְּגִין דְּאִית לוֹן חוּלָקָא בִּסְפִירָן, מַה דְּלָאו הָכֵי בְּמַלְאָכִין. בְּגִין דְּיִשְׂרָאֵל אִנּוּן ערביה וְאַחֲסַנְתֵּהּ, כְּגַוְנָא דִּבְנִין לְגַבֵּי אֲבוּהוֹן. דְּמַלְאָכִין לָאו אִנּוּן לְגַבֵּי סְפִירָן אֶלָּא כְּסוּסְוָן לְגַבֵּי רוֹכְבֵי עָלַיְהוּ. אֲבָל יִשְׂרָאֵל בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאוֹקְמוּהּ מ\"מ אֵין יִשְׂרָאֵל נִגְאָלִין עַד שֶׁיִּשְׁתַּעְבְּדוּ בְּשִׁבְעִין וּתְרֵין אֻמִּין. וּבְגִין דָּא כָּלַל קוּדְשָׁא בְּרִיךְ הוּא בְּסַנְחֵרִיב ע\"ב אֻמִּין, לְקַיִּם בְּהוֹן מִ'לְחָמָה לַ'ה' בַּ'עֲמָלֵק מִדּוֹר דּוֹר. וְלָקֳבֵל ע\"ב שָׂרִים אִנּוּן שְׁמָהָן שִׁבְעִין וּתְרֵין דְּוַיִּסַּע וַיָּבֹא וַיֵּט, לְקַיְּמָא בְּהוֹן הִנֵּה ה' רוֹכֵב עַל עָ\"ב קַ\"ל, לְנָטְלָא מִנַּיְהוֹן נוּקְמָא מֵעֲמָלֵק דְּכָלִיל עָ\"ב אֻמִּין בֵּהּ. וְלָקֳבֵל ע\"ב שְׁמָהָן אִיהוּ וַיְכֻלּוּ דְּסָלִיק ע\"ב. וְדָא עָלֵהּ אִתְּמַר דְּזָרַע כָּל זִרְעוֹנִין בְּבַת אַחַת יְחִידָה וְהִיא כַּלָּה שַׁבַּת מַלְכְּתָא מִן קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ תִּפְאֶרֶת וּמַעֲשֶׂה דִּילֵהּ. וּבְגִין דְּכָל בִּרְיָן דִּבְרֵאשִׁית אִתְכְּלִילָן בֵּהּ, לְכָךְ הִתְחִילָה תּוֹרָה בְּבֵי\"ת מִן בְּרֵאשִׁית. וְאִיהִי בַּת זוּגֵהּ דְּתִפְאֶרֶת אָדָם כָּל חַד יָהִיב בֵּהּ חוּלָקֵהּ. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לָהּ רַב וְשַׁלִּיט עָלַיְהוּ, בְּגִין דְּכֻלְּהוּ אִתְבְּרִיאוּ בְּאָת יוּ\"ד בַּת יְחִידָא כְּלִילָא מֵעֶשֶׂר אֲמִירָן, וְעֶשֶׂר אֱלֹהִים. ה' כְּלִילָא מֵחָמֵשׁ אוֹרְיָן אוֹר דְּיוֹמָא קַדְמָאָה. ו' שִׁית סָמְכִין דִּקְשׁוֹט. יוֹם הַשִּׁשִּׁי ה' בְּגִין דִּבְיוֹם הַשִּׁשִּׁי וְאִשְׁתְּלִים ה' בְּבַת אַחַת. תָּא חֲזֵי כַּד אִית לִסְפִירָן לְמֶעֱבַד פְּעֻלָּה בְּשֵׁם יְדִיעַ, דְּמִתַּמָּן פְּעֻלָּה, לֹא אִשְׁתְּלִים וְלֹא אִתְעֲבִיד עַד דְּכָל סְפִירָה יָהִיב תַּמָּן חוּלָקָא. (נ\"א חולהא) דָּא יָהִיב תַּמָּן אַתְוָן דְּאִנּוּן כָּל גּווָֹנִין אֻכָּמִין מִסִּטְרָא דְּבַת יְחִידָה. וְאִנּוּן סוּמָקִין נִקּוּדִין מִסִּטְרָא דִּתְלָת אֲבָהָן. וְדָא יָהִיב וְכוּ' עַד דְּאִתְכְּלִיל בְּהַהוּא שְׁמָא כָּל סְפִירָן עכ\"מ:</p>"],[9514015413,"<p>אָמַר רִבִּי שִׁמְעוֹן מַאי וַיַּרְא אֵלָיו. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא כְּגַוְנָא דְּאַחֲזֵי לְאָדָם קַדְמָאָה, דּוֹר דּוֹר וּפַרְנָסָיו דּוֹר דּוֹר וּמַנְהִיגָיו, הָכֵי אַחֲזֵי לֵהּ לְאַבְרָהָם וְאָמַר, בְּהַאי דָּרָא יְהוֹן צַדִּיקִים, וּבְהַאי דָּרָא בֵּינוֹנִיִּים, וּבְהַאי דָּרָא רְשָׁעִים. אָמַר רִבִּי יוֹסֵי, בּוּצִינָא קַדִּישָׁא, הָא אוֹקְמוּהּ הַכֹּל בִּידֵי שָׁמַיִם חוּץ מִיִּרְאַת שָׁמַיִם, וּקְרָא אָחֳרָא כְּתִיב מִפִּי עֶלְיוֹן לֹא תֵצֵא הָרָעוֹת וְהַטוֹב. וְאִם קֹדֶם דְּאַתְיָן לְעָלְמָא, אִתְגְּזַר עָלַיְהוּ לְמֶהֱוֵי צַדִּיקִים אוֹ רְשָׁעִים אוֹ בֵּינוֹנִיִּים, לָא הֲוָה עָתִיד לְמֶהֱוֵי לוֹן אַגְרָא וְעוֹנְשָׁא, וְלָא הֲוָה לֵהּ לַנָּבִיא לְמֵימַר לוֹן מַתְנִיתִין לְמֵימַר, הַכֹּל בִּידֵי שָׁמַיִם חוּץ מִיִּרְאַת שָׁמַיִם. אָמַר רִבִּי שִׁמְעוֹן שְׁאִלְתָּא דָּא עֲמִיקָא, וְאַפְלִיגוּ בָּהּ קַדְמָאֵי, וְסַגִּיאִין כָּשְׁלוּ בָּהּ. בְּגִין דְּלָא מָטוּ לְעוּמְקָא דְּרָזָא. עַל נָבִיא אִתְּמַר הַאי קְרָא, (ירמיהו א׳:ה׳) בְּטֶרֶם אֶצָּרְךָ בְּבֶטֶן יְדַעְתִּיךָ. וְרָזָא דָּא הַכֹּל צָפוּן, וְהָרְשׁוּת נְתוּנָה, הָא מִלִּין אִלֵּין סְתִימִין, וְלָא אִתְגַּלְּיָן אֶלָּא בְּמַאי דְּאוֹקְמוּהּ רַבָּנָן, מַחֲשָׁבָה טוֹבָה הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרְפָהּ לְמַעֲשֶׂה. מַחֲשָׁבָה רָעָה אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרְפָה לְמַעֲשֶׂה. מַחֲשָׁבָה טוֹבָה הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרְפָהּ לְמַעֲשֶׂה, אוֹלִיפְנָא מֵהָכָא דְּקֹדֶם דְּאַתְיָא לְעוֹלָם, צָלֵי בְּגִינֵהּ וְשַׁוֵּי מַחֲשַׁבְתֵּהּ בֵּהּ בְּשַׁעֲתָא דְּזִוּוּגָא, וּבְגִין דָּא כְּתִיב בְּטֶרֶם אֶצָּרְךָ וְכוּ' וּבְטֶרֶם. חַד עַל דְּצָלֵי בְּגִינֵהּ קֹדֶם דְּאָתָא לְעָלְמָא. בְּגִין דְּשַׁוֵּי מַחֲשַׁבְתֵּהּ בֵּהּ קֹדֶם יְצִירָתֵהּ בַּבֶּטֶן בְּשַׁעֲתָא דְּזִוּוּגָא. וּבְגִין דָּא בְּטֶרֶם אֶצָּרְךָ בַּבֶּטֶן יְדַעְתִּיךָ וּבְטֶרֶם תֵצֵא מֵרֶחֶם. וּבְגִין דְּאַקְדִּימַת לֵהּ בִּצְלוֹתָא וּבְמַחֲשַׁבְתֵּהּ קֹדֶם יְצַרְתִּיהָ וְקֹדֶם דְּנָפַק מֵרֶחֶם אִמֵּהּ אִיהוּ מְנַבֵּא עֲתִידוֹת קֹדֶם דְּיֵיתוּן לְעָלְמָא. כָּל שֶׁכֵּן קוּדְשָׁא בְּרִיךְ הוּא דְּיָדַע כָּל דָּרִין קֹדֶם דְּיֵיתוּן לְעָלְמָא. דְּקֹדֶם דְּיֵיתֵי כָּל בַּר נָשׁ לְעָלְמָא, קֹדֶם יְצַרְתִּיהָ מַלְאָךְ מְמֻנֶּה עַל הַהִיא טִפָּה, וְקוּדְשָׁא בְּרִיךְ הוּא גָּזִיר עָלֵהּ אִם יִהְיֶה נָבִיא אוֹ חָכָם אוֹ בַּעַל מִקְרָא וּמִשְׁנָה, אוֹ מָארֵי רוּחַ הַקֹּדֶשׁ, אוֹ מָארֵי בַּת קוֹל, דְּאִתְנְהִיג בַּת קוֹל בְּמִלּוּלָא דִּילֵהּ, וְיֵימָא הֲלָכָה כִּפְלוֹנִי. אוֹ אִם יִהְיֶה טִפֵּשׁ, אֲבָל רָשָׁע וְצַדִּיק לֹא קָא גָּזַר. אַף עַל גַּב דַּאֲבוֹי עָבֵד. לֵהּ בְּמַחֲשָׁבָה רָעָה, דְּעָבִיד בֵּהּ מַעֲשֶׂה דְּעָבִיד לֵהּ בְּנִדָּה אוֹ כַּעֲרָיוֹת, אוֹ בִּגְוִיָּה אוֹ בְּזוֹנָה אוֹ בְּשִׁפְחָה.</p>"],[9514015414,"<p>אַף עַל גַּב דְּקוּדְשָׁא בְּרִיךְ הוּא יְדַע דַּהֲוֵי בֵּן רָשָׁע אוֹ מַמְזֵר קֹדֶם יְצִירָתֵהּ, לֹא מָנֵי קוּדְשָׁא בְּרִיךְ עַל אֲבוֹי לְמֶעֱבַד לֵהּ בָּעֲרָיוֹת אוֹ בְּנִדּוֹת, דְּהָא מָנֵי בֵּהּ בְּאוֹרַיְתָא עַל הַנִּדּוֹת וְעַל הָעֲרָיוֹת. הָדָא הוּא דִּכְתִיב וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִּקְרַב וְהַאי אִיהוּ דְּאִתְּמַר נָבִיא מִפִּי עֶלְיוֹן לֹא תֵצֵא הָרָעוֹת וְהַטוֹב. מַאי הָרָעוֹת וְהַטוֹב, אֶלָּא הָכֵי קוּדְשָׁא בְּרִיךְ הוּא לֹא גָּזַר עָלֵהּ דִּיהֵא צַדִּיק וָטוֹב. אֶלָּא קֹדֶם יְצִירָתֵהּ הוּא יָדַע מַחֲשָׁבָה דַּאֲבוֹי. וְקוּדְשָׁא בְּרִיךְ הוּא מַחֲשָׁבָה טוֹבָה מְצָרְפָהּ לְמַעֲשֶׂה. הַאי אִיהוּ כָּל חַד בִּפְרָט. וּבְגִין דָּא הַכֹּל צָפוּי בְּמַחֲשָׁבָה. דְּקֻדְשָׁא יָדַע מַחֲשַׁבְתֵּהּ בִּישָׁא. וְהָרְשׁוּת נְתוּנָה לֵהּ לָאָדָם בְּמַעֲשֶׂה. וְאָדָם חָב בְּמַחֲשָׁבָה וּבְעוֹבָדָא, וְגָרַם לְעָלְמָא דְּאִתְדְּבָקוּ בְּאִילָנָא דְּטוֹב וָרָע וְאִיהוּ חָזַר בִּתְיוּבְתָּא וְאִתְדַּבַּק, בְּאִילָנָא דְּחַיֵּי. וּבְגִין דְּכָל דָּרִין בֵּהּ תַּלְיָן, וְאוֹרַיְתָא דִּיהַב לֵהּ, יָהַב לְמֹשֶׁה וְכָל יִשְׂרָאֵל. וְכָל (נ\"א ובכל) דָּרִין וְכָל דָּרִין חָזָא בֵּהּ קוּדְשָׁא בְּרִיךְ הוּא דּוֹר דּוֹר וּפַרְנָסָיו, דּוֹר דּוֹר וּמַנְהִיגָיו. וּמְנָא לָן דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵהּ אוֹרַיְתָא, הָדָא הוּא דִּכְתִיב אָז רָאָה וַיְסַפְּרָהּ הֱכִינָהּ וְגַם חָקְרָה וַיֹּאמֶר לָאָדָם. אֲפִלּוּ שֵׁדִין וּמַזִּיקִין נָפְקוּ מִנֵּהּ. וְהַאי אִיהוּ פֹּקֵד עֲוֹן אָבוֹת עַל בָּנִים. אִלֵּין דְּמַעֲשֵׂה אֲבוּהוֹן בִּידֵיהוֹן. וְלֹא יוּמְתוּ אָבוֹת עַל בָּנִים וּבָנִים לֹא יוּמְתוּ עַל אָבוֹת, אִלֵּין דְּעוֹבָדָא דַּאֲבוּהוֹן לָאו בִּידֵיהוֹן. וְלֹא עוֹד אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא לֹא אָמַר דְּאַחֲזֵי לֵהּ לָאָדָם, וְלֹא לְאַבְרָהָם, וְלֹא לְשׁוּם נָבִיא, אֶלָּא דּוֹר דּוֹר וְדוֹרְשָׁיו וְכוּ', וְלֹא אָמַר דְּאַחֲזֵי לֵהּ צַדִּיקִים אוֹ רְשָׁעִים אוֹ בֵּינוֹנִיִּים, וְלָאו דְּגָזַר עָלַיְהוּ לְמֶהֱוֵי צַדִּיקִים אוֹ בֵּינוֹנִיִּים אוֹ רְשָׁעִים. א\"ל רִבִּי יוֹסֵי בָּתַר דְּאַחֲזֵי לֵהּ דָּרָא דָּרָא וּפַרְנָסָיו, דָּרָא דָּרָא וּמַנְהִיגָיו וַדַּאי אִשְׁתְּמוֹדַע בְּהוֹן אִי אִנּוּן צַדִּיקִים אוֹ רְשָׁעִים אוֹ בֵּינוֹנִיִּים. א\"ל הָכֵי אִיהוּ וַדַּאי, אֲבָל רָזָא דְּמִלָּה עָמֹק הַנִּסְתָּרוֹת לַה' אֱלֹהֵינוּ:</p>"],[9514015415,"<p>אַדְּהָכִי הַהוּא סָבָא עִלָּאָה אִזְדְּמַן לְגַבַּיְהוּ וְאָמַר לוֹן, בְּמַאי עֲסִיקְתּוּ סָחוּ לֵהּ עוֹבָדָא. אָמַר לוֹן וַדַּאי אוֹרַיְתָא אִתְבְּרִיאַת תְּרֵי אַלְפֵי שְׁנִין קֹדֶם דְּאִתְבְּרֵי עָלְמָא, וּבָהּ אַחֲזֵי לְאָדָם הָרִאשׁוֹן דּוֹר דּוֹר וְדוֹרְשָׁיו וְכוּ', וּבָהּ אַחֲזֵי לְאַבְרָהָם אוּף הָכֵי. מַאי דִּכְתִיב בֵּהּ. וּבְגִין דָּא וְיִשְׁמֹר מִשְׁמַרְתִּי מִצְוֹתַי חֻקּוֹתַי וְתוֹרֹתַי. וּבָהּ נִמְלַךְ קוּדְשָׁא בְּרִיךְ הוּא וּבָרָא עָלְמָא. וְנִשְׁמָתְהוֹן דְּצַדִּיקַיָּא אוּף הָכֵי נִמְלַךְ בְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא וּבָרָא עָלְמָא. הָדָא הוּא דִּכְתִיב בְּרֵאשִׁית, וְאֵין רֵאשִׁית אֶלָּא תּוֹרָה. וְאֵין רֵאשִׁית אֶלָּא נְשָׁמָה. וְאוֹרַיְתָא טְפֵלָה לַנְּשָׁמָה, בְּגִין דְּשַׁבָּת שָׁקוּל כְּנֶגֶד כָּל הַתּוֹרָה כֻּלָּהּ, וּמְחַלְּלִין לֵהּ בְּגִין נִשְׁמְתָא דְּבַר נָשׁ דְּלָא תִּפּוֹק מִנֵּהּ קָדָם זְמָנֵהּ. וְאִיהִי נִשְׁמְתָא דָּא נְבוּאִית בָּהּ נִבְרָא עָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁלַח לֵהּ בְּכָל דָּרָא וְדָרָא לְאַגָּנָא עֲלוֹי וּלְמִסְבַּל עֹל דִּילְהוֹן, בְּגִין דְּאִיהִי מֵאִילָנָא דְּחַיֵּי, דְּלָא תַּלְיָא מִנֵּהּ זְכוּת וְחוֹבָה, לָא אַגְרָא וְלָא עוֹנְשָׁא, דְּאִנּוּן עֵץ הַדַּעַת טוֹב וָרָע. וְכָל דּוֹר לֵית הֲוָא פָּחוֹת מִשִּׁשִּׁים רִבּוֹא שֻׁלְטָנוּתָא דְּהַהִיא נִשְׁמְתָא. וְאַחֲזֵי לְאָדָם אִם דָּרָא יְהֵא זַכָּאָה, בַּר נָשׁ יְקוּם לְמֵידַת נִשְׁמְתָא מִסִּטְרָא דְּחֶסֶד, וִיהוֹן זַכָּאִין מִסִּטְרָא דְּחֶסֶד, וּמַטֶה לוֹן כְּלַפֵּי חֶסֶד, וְדָרָא דָּא יְהוֹן מָארֵי חִנָּא וְחִסְדָּא. וְאִי לָא מִתְנַהֲגִין בְּדַרְגָּא דִּילְהוֹן דְּאִיהוּ מְמָנָא עַל דָּרָא וּפַרְנָסִין דִּילֵהּ דִּיהוֹן חֲסִידִין, קוּדְשָׁא בְּרִיךְ הוּא אַעֲבַר מִנְּהוֹן חֶסֶד, וְשַׁלִּיט עָלַיְהוּ גְּבוּרָה מִדַּת הַדִּין, לְמֵידַן לְהוּ כְּפוּם עוֹבָדַיְהוּ, וְלֹא כְּפוּם דַּרְגָּא וּמוֹלָדָא וּמַזָּלָא דִּילְהוֹן. וְרָזָא דְּמִלָּה דָּא קָא רְמִיזָא לָן בְּהַגָּדוֹת וּדְרָשׁוֹת, דְּאוֹקְמוּהּ מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, אִלֵּין תְּרֵין מְשִׁיחִין דַּעֲתִידִין לְמַיְתֵי בְּהַנֵּי דָּרֵי. אִם דָּרָא אִיהוּ חַיָּבָא אִתְקְיַם בְּהוֹן מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר.</p>"],[9514015416,"<p>וְעוֹד אוֹלִיפְנָא בְּרָזָא דָּא מִלָּה אָחֳרָא לְסַמְכָא לְגַבֵּהּ בְּשַׁגַּם הוּא בָּשָׂר. וְאוֹקִימְנָא בְּשַׁגַּם זֶה מֹשֶׁה, דְּעָתִיד הוּא לְמֵיהַב אוֹרַיְתָא בְּדוֹר הַמַּבּוּל. אֶלָּא דַּהֲווֹ רַשִּׁיעַיָּא, וְקוּדְשָׁא בְּרִיךְ הוּא גָּנִיז לֵהּ לְצַדִּיקַיָּא. אוּף הָכֵי מִזְדַּמְּנָא הָיְתָה בַּת שֶׁבַע לְדָוִד מִשֵּׁשֶׁת יְמֵי בְּרֵאשִׁית, אֶלָּא שֶׁאָכְלָה פָּגָה, וְאוֹלִיפְנָא דְּחוֹבִין דְּבַר נָשׁ, גַּרְמִין דְּלָא יִזְכֵּי לְטוֹבָה דְּמִזְדַּמְּנָא עָלֵהּ לְמֶהֱוֵי מִשֵּׁשֶׁת יְמֵי בְּרֵאשִׁית. אוּף הָכֵי דָּרָא טָבָא מַרְעִין בִּישִׁין דַּעֲתִידִין לְמֶהֱוֵי. אִית לְמָאן דְּאִתְרְחַק מִנֵּהּ, עַד דְּמִתְקַן עוֹבָדוֹי וְאַחֲזַר לֵהּ אֲבֵדָה דִּילֵהּ. וְאִית דְּאָבִיד לֵהּ בְּחוֹבוֹי וְלָא אִתְחֲזַר לֵהּ לְעוֹלָם. וְהַאי אִיהִי אֲבֵדָה דְּאִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה, וְאִיהוּ דְּזָכָה בַּמְּצִיאָה קָנָה לָהּ, אִי אַקְדִּים בָּהּ לְחַבְרֵהּ. וְהַאי אִיהוּ דְּקוּדְשָׁא בְּרִיךְ הוּא אַחֲזֵי לְכָל עָלְמָא, שִׁתָּא אַלְפֵי שְׁנִין וְחַד חָרוּב. וְאַחֲזֵי דִּבְכָל אל'ף קַדְמָאָה שׁוּלְטָנוּתֵהּ חֶסֶד. באל'ף תִּנְיָנָא שׁוּלְטָנוּתֵהּ גְּבוּרָה דָּרִים בִּתְרֵין דַּרְגִּין גִּבּוֹרִים וַחֲסִידִים. וְאֶלֶף תְּלִיתָאָה שׁוּלְטָנוּתֵהּ לְמֶהֱוֵי דָּרִים דִּילֵהּ אַנְשֵׁי אֱמֶת. אֶלֶף רְבִיעָאָה שׁוּלְטָנוּתֵהּ נֶצַח. וְאֶלֶף חֲמִישָׁאָה שׁוּלְטָנוּתֵהּ הוֹד, וַהֲווֹ עֲתִידִים לְמֶהֱוֵי דָּרִים דִּלְהוּ נְבִיאִים. אֶלֶף שְׁתִיתָאָה צַדִּיק יְסוֹד עוֹלָם. וְאִם ח\"ו בַּאֲתַר דְּדַרְגָּא דִּילְהוֹן מְחַיֵּב לוֹן לְמֶהֱוֵי צַדִּיקִים וְאִנּוּן רְשָׁעִים, כְּאִלּוּ עַבְרִין עַמּוּד צַדִּיק יְסוֹד עוֹלָם מֵעָלְמָא, וְחָזְרִין עָלְמָא לְתֹהוּ וָבֹהוּ, וְשַׁלִּיט עָלַיְהוּ בַּאֲתַר דְּצַדִּיק, סמאל הָרָשָׁע. אוּף הָכֵי אִם דָּרִים דְּנֶצַח וְהוֹד רַשִּׁיעַיָּא בַּאֲתַר דִּנְבִיאֵי הָאֱמֶת, שַׁלִּיטִין נְבִיאֵי הַשֶּׁקֶר. וְאִם דָּרָא דֶּאֱמֶת לֹא מַנְהִיגִין בֵּהּ, אִסְתְּלַק מִנַּיְהוּ אֱמֶת וְשָׁלְטָא עָלַיְהוּ שֶׁקֶר. וְאִם דָּרִין דִּגְבוּרָה לָאו גְּבוּרָה עוֹמְדִים בַּפֶּרֶץ, אִסְתְּלַק מִנַּיְהוּ גְּבוּרָה וְשַׁלִּיט נוּכְרָאָה עָלַיְהוּ, עָלַיְהוּ כָּךְ גַּם כֵּן לְקָבְלְהוֹן לְתַתָּא, י\"ב שִׁבְטִין קַיְּמִין סַחֲרָנֵי מַשְׁכְּנָא בְּהַאי גּווָֹנָא, כָּל חַד מִנַּיְהוּ בְּדוּכְתָא דְּאִתְחֲזֵי לֵהּ. וְלָקֳבֵל הַאי דַּרְגָּא עֶבֶד שְׁלֹמֹה לְתַתָּא יָם עוֹמֵד עַל שְׁנֵים עָשָׂר בָּקָר, שְׁלֹשָׁה פּוֹנִים צָפוֹנָה, וּשְׁלֹשָׁה פּוֹנִים דָּרוֹם, וְג' פּוֹנִים מִזְרָח, וְג' פּוֹנִים מַעֲרָב. וְהַאי דַּרְגָּא לְעֵלָּא, מ\"ט אִקְּרֵי יָם. אֶלָּא בְּגִין דְּהַהוּא צַדִּיק דְּאַמְלֵי לְהַאי יָם, אִקְּרֵי יוֹם. הָדָא הוּא דִּכְתִיב וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. וּכְתִיב אוֹר זָרֻעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה. וְהוּא נָהִיר בְּרָזָא דְּוָא\"ו דִּשְׁמָא קַדִּישָׁא. וְהַהוּא יוֹם בְּרָזָא דְּחֵילָא דִּשְׁמָא קַדִּישָׁא, דְּבֵהּ אַמְלֵי לְהַאי יָם דְאִקְּרֵי ה'א תַּתָּאָה דִּשְׁמָא קַדִּישָׁא. הָדָא הוּא דִּכְתִיב כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. וְכָל דָּא דַּרְגָּא דְּצַדִּיק בְּגִין דְּכָל תַּפְנוּקִין מִנֵּהּ נָפְקִין.</p>"],[9514015417,"<p>מַאי הַנְּחָלִים, אִלֵּין חָמֵשׁ דַּרְגִּין דְּעִמֵּהּ הוֹלְכִים אֶל הַיָּם לְמִמְלֵי לֵהּ. וְהַאי דַּרְגָּא אִקְּרֵי בַּת שֶׁבַע. וְכַד נָהִיר הַאי צַדִּיק לְהַאי דַּרְגָּא דְאִקְּרֵי צֶדֶק, לְהַאי דַּרְגָּא דְאִקְּרֵי שִׁבְעָה שָׁבוּעִין שִׁבְעָה זִמְנִין, כְּדֵין עָלְמָא תַּתָּאָה נַמֵּי הַאי דַּרְגָּא דְאִקְּרֵי סִיהֲרָא דְּשָׁלְטָא בְּלֵילְיָא, שְׁנַת הַלְּבָנָה כַּמָּה סַגִּי שנ\"ה יוֹמִין וְאַרְבְּעִין וְתֵשַׁע שָׁבוּעִין, מִנְּהוֹן לָקֳבֵל הַאי דַּרְגָּא דְּיָם דִּלְעֵלָּא, דְּאִיהִי מְקַבְּלָא מִנֵּהּ. אִשְׁתְּאֲרוּ י\"ב יוֹמִין לָקֳבֵל י\"ב שִׁבְטִין דְּסַחֲרָנֵי הַאי יוֹמָא, לִמְטַר מִטְרַת מַשְׁכְּנָא וְכֹלָּא לְאַחֲזָאָה חֵילָא עִלָּאָה. וע\"ד כְּתִיב כָּל הַנִּקְרָא בִּשְׁמִי דָּא דַּרְגָּא דְּצַדִּיק, דְּאִיהוּ נָהִיר בְּחֵילָא דִּשְׁמֵהּ קַדִּישָׁא, הָדָא הוּא דִּכְתִיב וְלִכְבוֹדִי בְּרָאתִיו, דָּא יַמָּא בְּחָכְמְתָא דְאִקְּרֵי כָּבוֹד. יְצַרְתִּיו דָּא רָזָא דְּיוֹם לְתַתָּא דְּאִיהוּ לָקֳבֵל כָּל דִּלְעֵלָּא. אַף עֲשִׂיתִיו דָּא סִיהֲרָא דִּלְתַתָּא. וע\"ד כְּתִיב יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ, דַּרְגָּא דְּשִׁמְשָׁא וְסִיהֲרָא. כְּדֵין כַּד אִתְחַבָּרוּ עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, וּכְדֵין שְׁלָמָא לְעָלְמָא. הָדָא הוּא דִּכְתִיב וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וּכְדֵין יִחוּדָא לְעֵלָּא וְיִחוּדָא לְתַתָּא שְׁלָמָא לְעֵלָּא וּשְׁלָמָא לְתַתָּא. שֶׁנֶּאֱמַר שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב:</p>"],[9514015418,"<p>מַתְנִיתִין בִּטְהִירוּ בְּרֵישׁ הוֹרְמָנוּתָא דְּמַלְכָּא, גָּלִיף תֵּשַׁע גְּלִיפִין בְּגַלְגַּלּוֹי טְהִירִין, וְחַד טָמִיר וְלָא יְדִיעַ. גָּלִיף גְּלִיפִין וּבָטַשׁ גּוֹ בּוּצִינָא חֲדָא, וְנָפִיק א הֵימֶנּוּ דְּחַד הוֹרְמָנוּתָא טָמִיר בִּטְמִירוּ יְדִיעַ וְלָא יְדִיעַ. כָּל סוּכְלְתָנוּ בֵּהּ הָדְרָא לַאֲחוֹרָא. זְעֵיר הוּא, וּמִגּוֹ זְעֵירוּתָא דִּילֵהּ טָמִיר בִּסְתִימוּ דְּמֵעוֹי וְלָא יְדִיעַ. כָּל הִרְהוּרִין בֵּהּ מְשַׁבְּשָׁן, תֵּבִין וְהַדְרָן וְלָא אִתְדַּבָּקוּ. בֵּהּ סְתִימִין תְּלָתִין וּתְרֵין עַיְנִין, אִנּוּן עַיְנִין לָא פְּתִיחָן. רְשִׁימָן אִנּוּן בִּרְשִׁימוּ זְעֵיר. בֵּהּ סָלְקִין הִרְהוּרִין וְעוֹבָדִין וְלָא גַּלֵּי טַעֲמַיְהוּ. כָּנִישׁ לוֹן בְּשַׁעֲתָא דְּאִזְדְּרִיקוּ, וּבְשַׁעֲתָא דְּאִתְכְּנִישׁוּ זָרִיק לוֹן. בֵּהּ מִתְצַיְּרָן צִיּוּרִין סְתִימִין וְלָא גַּלְיָן. גָּלִיף גְּלִיפִין וּבָטַשׁ וְנָפַק ב' חַד דִּלְתַתָּא דְּסַחֲרָא. סְחוֹר סְחוֹר וּפָרְחָא בָּאֲוֵירָא. בָּטַשׁ בַּמַּגְדְּלָא וְאִסְתְּחַר הֵיכָלָא מִגּוֹ אֲוֵירָא דְּפָרְחָא, בֵּהּ שַוְיָן צִיּוּרִין אֻמָּנִין בְּכָל מָאנֵי כֶּסֶף וּדְהַב וּנְחָשָׁא. אָזְלָא וְאִתְטַמְּרָא וְלָא אִשְׁתְּמַע קָלֵהּ לְבַר. לְגוֹ בִּמְעוֹי שְׁמִיעַ קָל דְּלָא אִתְיְדַע, וְהַהוּא קָלָא נָפִיק מְסַיְּפֵי דְּעָלְמָא עַד סַיְפֵי דְּעָלְמָא, סָלְקָא וְנָחְתָא אָזְלָא וּקְיָמָא, עֵינָא לָא שָׁלְטָא לְמֶחֱמֵי בְּשַׁעֲתָא דְּאִתְכַּסֵּי אִתְגַּלְּיָא, וּבְשַׁעֲתָא דְּאִתְגַּלְּיָא אִתְכַּסֵּי. בִּסְתִימוּ דְּעַיְנִין חָמָאן לֵהּ. בַּאֲטִימוּ דְּאוּדְנִין שָׁמְעִין לֵהּ. בִּפְתִיחוּ דְּעַיְנִין אִתְכַּסֵּי לֵהּ. וְלָא יְדִיעַ עַד דְּאִזְדַּמִּין לְפָתוֹרֵהּ זַכָּאֵי קְשׁוֹט לְמֵיכַל. גָּלִיף גּוֹ גְּלִיפָא דְּצִיּוּרָא וְנָפַק ג' דְּאִתְכַּסֵּי חוֹשְׁנָא וְאֵפוֹדָא. מְזָרַז בְּהֵמְיָינָא. אִתְגַּלֵּי בִּימָמָא וְאִתְכַּסֵּי בְּלֵילְיָא. נָפַק זִמְנָא חֲדָא וְאִתְחָרַט וְאַגְנִיז, עַד דְּאָתֵי ו' אָחִיד בֵּהּ וְאִתְפְּיַס וְתָב לְדוּכְתֵּהּ, וְלָא בָּעֵי לְאִתְגַּלָּאָה אֶלָּא לְאִנּוּן דְּקָארָן לֵהּ בְּלֵילְיָא. וּבְצַפְרָא גַּלֵּי רְשִׁימוּ דְּחוּטָא סָעִיר דַּקִּיק דְּאִתְחַבַּר בַּהֲדַיְהוּ בִּימָמָא בְּגוֹ שִׁירוּתָא וְחֶדְוָה דִּמְזַמְּרָן לֵהּ בְּלֵילְיָא. וְעָבִיד טִיבוּ לְכֹלָּא, סָלִיק דִּגְלָא לִימִינָא וְאִתְרְשִׁים וְקִיִּם עָלְמָא. עָאל גּוֹ הֵיכָלִין פְּנִימָאִין וְנָפַק וּבָבֵי עָלְמָא שִׁירוּתָא וְסוֹפָא אִיהוּ טָמִיר בְּשִׁתִּין רִבְוָן עָלְמִין, בִּסְטָר דָּרוֹמָא שָׁארֵי וְנָפַק וְאָחִיד מַגְרוֹפַיָּא וְאַפִּיק מְזוֹנָא לְכֹלָּא וְנָהִיר לוֹן. גָּלִיף גְּלִיפוּ דִּטְהִירוּ דְּטִיהֲרָא דַּכְיָא, וְאַפִּיק ד' בְּחֻשְׁבָּנָא (נ\"א בחשבא) דְּמָאתָן אֶלֶף עָלְמִין עִרְטוּרָא דִּנְהוֹרָא דְּנָהִיר. מִנֵּהּ נָפְקָן עֲמִיקָן לְגַלָּאָה. נְהֹרָא דְּנָהִיר וְאִתְטְמַר וְאִתְחֲשָׁךְ. אִיהוּ דָּחֵי וְאָחֳרָא מְקָרֵב. אִיהוּ מָחֵי וְאָחֳרָא מָסֵי. בִּידֵהּ שַׁרְבִיט דְּחַיֵּי וּמוֹתָא. טָמִיר בְּאַרְבַּע מֵאָה אַבְנִין מַגִּיחֵי קְרָבָא, מָארֵי דְּרוֹמְחֵהּ וְחַרְבָּא דִּמְלַהֲטָא, דְּמִתַּמָּן נָפְקִין וּמִתְפַּשְּׁטָן בְּלָא חֻשְׁבָּנָא. כַּד אַגְלִיף גְּלִיפוּ בְּהִתּוּכָא דְּנוּרָא דְּדָלִיק, נָפִיק מִנֵּהּ חַד סֻמָּקָא כִּוְרָדָא. שַׂעֲרוֹי תַּלְיָן כְּרוּבֵי דְּטוּרֵי חָשׁוּךְ. דָּחִילֵי וְאֵימָתֵנוּ תַּקִּיפָא יְתֵירָא הוֹסַפְתָּ בֵּהּ. יְדוֹי דְּבֵקָן בְּשַׁלְהוֹבָא דְּחַרְבָּא מְהַפְּכָא. יוֹמָא דְּיִתְּעַר, כֹּלָּא עַבְרִין קַמֵּהּ כִּבְנֵי מָרוֹנָא.</p>"],[9514015419,"<p>זַכָּאָה אִיהוּ מָאן דְּקָרִיב בֵּהּ וְאִשְׁתְּזִיב מִנֵּהּ. גָּלִיף גְּלִיפִין דְּטוּרֵי נְהִירוּ וְאַפִּיק ה' דְּקַיְּמָא גּוֹ עַמּוּדִין דְּעָלְמָא, כֹּלָּא קַיְּמִין קַמֵּהּ וְיָתִיב בֵּינַיְהוּ כְּמַלְכָּא גּוֹ חֵילֵהּ. תְּרֵין רַבְרְבִין מְמָנָן קַיְּמִין לָקָבְלֵהּ, עָבִיד שְׁלָמָא בֵּינַיְהוּ. בְּשַׁעֲתָא דְּאִתְגְּלֵי. כֹּלָּא קַיְּמִין בְּקִיּוּמַיְהוּ. סָגִיר וּפָתַח. וּבְגִינֵהּ קַיְּמִין שִׁתִּין אֶלֶף רִבּוֹא עַל טוּרִין סַגִּיאִין. וְכָל מַפְתְּחָן דְּמַלְכָּא בֵּהּ קַיְּמִין. עָבִיד כִּרְעוּתֵהּ וְלֵית מָאן דְּיִמְחֵי בִּידֵהּ. סְתִימִין עִלָּאִין רָמִין טְמִירִין קַיְּמִין עָלֵהּ וְחַדָּאָן בֵּהּ, כָּוֵי נְהוֹרָא מִנֵּהּ פְּתִיחָן וְנַהֲרָן. חוֹתָמָא טְמִירָא דְּמַלְכָּא בִּידֵהּ, עָבִיד כִּרְעוּתֵהּ בְּחִיל שְׁמַיָּא וְדַיָּרֵי אַרְעָא. גּוֹ אֲצִילֵי יְדוֹי יְדוּרוּן תְּלָת מֵאָה אֶלֶף רִבּוֹא עָלְמִין. אוֹרְכֵּהּ מְסַיְּפֵי עָלְמָא וְעַד סַיְּפֵי עָלְמָא. יָתִיב עַל כֻּרְסֵא דִּשְׁבִיבִין דִּנּוּר. מִנֵּהּ נַהֲרִין עָלְמִין מִנֵּהּ אִתְזָנוּ, חַד הוּא חַד לֶהֱוֵי חַד אִקְּרֵי, בְּרִיךְ הוּא לָעֳלָם וּלְעָלְמֵי עָלְמִין. גָּלִיף גָּלִיף וּבָטַשׁ בְּצִיּוּרָא וְאַפִּיק ו' (נצח) דְּאָזְלָא תָּדִיר וְאָחִיד דְּחַיִּין, וְשָׁחִיק נְהִירִין לְמֵיזָן עָלְמִין בְּאִנּוּן נְהוֹרִין דְּשָׁחִיק. חָמֵשׁ סִימָנִין דִּקְטֹרֶת בּוּסְמִין אִתְעָרְבָן בַּהֲדַיְהוּ. אִיהוּ שָׁחִיק וְנָהִיר וְלָא אִתְבַּסַּם לְבַר. טָמִיר גַּרְמֵהּ דְּלָא יִתְבַּסֵּם וְלָא יְרִיחוּן בֵּהּ רֵיחָא. קַדְמָא לְשִׁמּוּשָׁא בְּרָזָא דת\"ק רָזִין דְּמַלְכָּא. קָאֵם עַל קִיּוּמֵהּ וּמַלְכָּא תָּמִיךְ עָלֵהּ. בֵּהּ שַׁרְיָן כָּל אִנּוּן מְהֵימְנֵי קְשׁוֹט. חַד חַבְרָא אִית לֵהּ יָהִיב רְשׁוּ דָּא לְדָא מיומ' דַּהֲווֹ. אוֹלְפֵי הָכֵי גָּלִיף וּבָטַשׁ בְּגַלְפוֹי וְאַפִּיק: ז'. (הוד) הַהוּא מְהֵימָנָא אָחֳרָא דִּלְגַבֵּי חברי'. כָּל אוּמָנוּתֵהּ דְּחַבְרֵהּ אִיהוּ עָבִיד, קָאִים לְגַבֵּהּ בְּרַעֲוָא סַגֵּי. דָּא עַל דָּא קָאִים, נָטִיל. מְהֵימָנִין אִנּוּן לְמֶעֱבַד טִיבוּ לְבֵי דָּוִד אַבְרָהָם רְחִימָא תָּמִיךְ עַל דָּא יִצְחָק קָרְבְּנָא שְׁלִים תָּמִיךְ עַל דָּא. יַעֲקֹב שְׁלִימוּ דְּכֹלָּא קָאִים וְתָמִיךְ עָלַיְהו. כַּחֲדָא אִנּוּן וְאִתְחַפְיָן בַּעֲשָׁשִׁיתָא דִּמְקַבֵּל שִׁמְשָׁא י גָּלִיף גְּלִיפִין וּבָטַשׁ בּוּצִינָא וְאַפִּיק ח' (יסוד) וְדָא תְּמִינָאָה לְחֻשְׁבָּנָא, וְאַפִּיק חַד רְחִימָא דְּכֹלָּא תְּאוּבְתָּא דְּכֹלָּא. זַכָּאָה דְּכֹלָּא מְהֵימָנָא דְּכֹלָּא, דִּיּוֹקְנָא דְּהַהוּא שְׁלִים.</p>"],[9514015420,"<p>זִיהֲרָא דְּמִתְפְּשַׁט לְד' זָהֲרִין, הוּא נָעִיץ בְּאַרְעָא וְרֵישַׁיָּא מָטֵי לְצַיִת שְׁמַיָּא. עַפְיָא שַׁפִּיר וְאִנְבֵּהּ סַגֵּי, וּמָזוֹן לְכֹלָּא בֵּהּ. תְּחוֹתֵהּ תַּטְלֵל הַהִיא חַיּוּתָא דְּאִתְחַמַּם לְד' סִטְרִין דְּעָלְמָא. בְּעַנְפוֹי יְדֻרָון צִפֳּרֵי שְׁמַיָּא. אָזַל ועף בַּחֲמֵשׁ מֵאָה עָלְמִין וְאַפִּיק מֵיכְלָא מִכֻּלְּהוּ, וְאִיהוּ נָטִיל וְגַבֵּי מִנַּיְהוּ דָּא יָהִיב נֶחָמָא, וְדָא יָהִיב מַיָּא, וְדָא יָהִיב מִשְׁחָא, וְדָא יָהִיב מְנָא. וְאִיהוּ גַּבֵּי וְאָעִיל בְּאוֹצָרָא דְּמַשְׁכְּנֵי, וְאִיהוּ טָמִיר לֵית בֵּהּ דִּיּוֹקְנָא לְאִסְתַּכְּלָא לְבַר. נְהִירוּ דִּילֵהּ מִסַּיְפֵי דְּעָלְמָא וְעַד סַיְפֵי דְּעָלְמָא. כָּל חַיִּין בֵּהּ שַׁרְיָן, וְאִיהוּ יָהִיב לְמָאן דְּלֵית לֵהּ חַיִּין כְּלָל. עָאל לְאִנּוּן חֲמֵשׁ מֵאָה עָלְמִין, וְנָטִיל מִנַּיְהוּ חַמְשִׁין שְׁנִין וְלָא יַתִּיר, וְאִיהוּ יָהִיב. לְבָתַר עָאל לְגַבֵּי אַבָּא וְאִמָּא, וּמִמַּה דְּיָהֲבֵי לֵהּ יָהִיב אִיהוּ וְאַשְׁלִים לְשִׁבְעִין. אִתְגַּלֵּי בִּימָמָא אִתְחַם לִתְרֵיסַר תְּחוּמִין. שִׁבְעִין תְּמָרִים וּתְרֵיסַר מַבּוּעִין דְּנָבְעִין בֵּהּ תַּלְיָן זַכָּאִין אִקְּרוּן עַל שְׁמֵהּ. בְּכָל מֵיכַל וְכָל עִבּוּרָא דְּכָל עָלְמָא, אִיהוּ לָקִיט וְאִיהוּ יָהִיב. בְּרִיךְ דוּכְרָנֵהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: גָּלִיף בְּתֻקְפָּא גְּלִידָא דְּתַקִּיפוּ חַד וְאַפִּיק ט', וְאִיהוּ גְּרָמָא תְּשִׁיעָה דְּסָלְקָא בִּימָמָא וְנָחִית בְּלֵילְיָא. טְמִירָא בִּתְלָת מֵאָה וְשִׁתִּין וְחָמֵשׁ דִּיּוֹקְנִין טְמִירִין. אָזְלָא וְנָחְתָא וְקַיְּמָא טְמִירִין בֵּין תְּרֵין דְּרוֹעֵי דְּמַלְכָּא: גְּלִיפָא בְּעִזְקָתָא דְּשַׁרְבִיטָא דְּגֻשְׁפַּנְקָא. פַּרְוַונְקָא דְּנָטִיר בְּאוֹרְחָא, דְּאֵין דִּינִין וְיֵטִיב עַל עִיּוּנָא דִּסְפָרִין פְּתִיחָן. טָב וּבִישׁ קַיְּמָא לְקָבְלֵהּ. מִסִּטְרֵהּ חַיִּין, וּמִסִּטְרֵהּ מוֹתָא. מִסִּטְרֵהּ מִתְקָא, וּמִסִּטְרֵהּ מְרִירוּ. חַד חִיוְיָא קָאִים לְקָבְלֵהּ רֵישֵׁהּ תְּחוֹת לְרַגְלֵהּ. בְּשַׁעֲתָא דְּאַפִּיק רֵישֵׁהּ מָחֵי בִּזְנָבוֹי. מָאן דְּאָערָע בְּקֶשֶׁר שַׁוֵּי מָאִיךְ לֵהּ עַד נוּקְבָא דִּתְהוֹמָא רַבָּה. קַיְּמָא רַגְלֵהּ עַל רֵישֵׁהּ דְּהַהִיא חִיוְיָא, כַּד אִסְתַּלַּק בָּקַע יַמָּא בַּאֲוֵירָא דְּמָטֵי וְלָא מָטֵי. קַיְּמָא בְּלֵילְיָא. פְּלַג נַכְסִין לְעוּתָרִין. יָהִיב מְזוֹנָא לְבֵיתֵהּ. אִתְחַבַּר וְאִתְטַמַּר בִּרְמַ\"ח אַנְפִּין. אִתְקַשַּׁט בְּקִשּׁוּטֵי מַלְכָּא. רִבּוֹן כָּל אַרְעָא אַגְנִיז בְּגַוֵהּ נְהוֹרָא דְּנָהִיר וְרָהִיט בַּאֲרוֹנָא לְאוֹרַיְתָא, אַגַּח קְרָבָא בְּשַׂנְאוֹי וְנָטִיל נוּקְמִין. מְזָרֵז גַּרְמֵהּ כִּגְבַר תַּקִּיף. חַרְבָּא מְשַׁנְּנָא בִּידֵהּ. רֻמְחֵהּ שְׁבִיבִין דְּנוּר. גִּירִין דְּזָרִיק לְהָטָן בִּתְקִיפוּ דְּאֶשָּׁא דְּאָכְלָא. בּוּצִינָא דְּשַׂרְגָּא דְּשָׁארֵי עַל רֵישַׁיְהוּ דְּזַכָּאֵי קְשׁוֹט. טְמִירוּ דְּאִנּוּן הֵיכָלִין דִּילֵהּ לֵית לֵהּ חֻשְׁבָּנָא. תְּחוּמִין דִּילֵהּ עַד שִׂפְתָּא דְּיַמָּא דְּגִנּוֹסָר. אִתְתַּחְמָא לְד' סִטְרִין. אַרְבַּע מַלְכִין מִתְצַיְּרָן מִגַּוֵּהּ. בְּהוּ שָׁלְטָא עַל עָלְמָא. תְּרֵי רַבְיָן קְבִיעָן תְּחוֹתֵהּ. טָס בְּהוּ בִּתְרֵיסַר (נ\"א בתמניסר) עָלְמִין וְאַגְנִיז תַּמָּן. בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן נֶצַח סֶלָה וָעֶד:</p>"],[9514015421,"<p>תם ונשלם - שבח לאל בורא עולם</p>"]]});
